/**
 * Chord positions from `@tombatossals/chords-db` (MIT): ranking a chord's
 * positions from easiest to hardest and turning one into SVGuitar data. Shared
 * by the editor's chord popup (guitar) and the strum player (guitar, ukulele).
 *
 * A position lists one fret per string, lowest string first (`-1` muted,
 * `0` open), relative to `baseFret`; `barres` names the relative frets a
 * finger lays across.
 */

export interface ChordDatabasePosition {
  frets: number[];
  fingers?: number[];
  baseFret?: number;
  barres?: number[];
  capo?: boolean;
  midi?: number[];
}

export interface ChordDatabaseEntry {
  key: string;
  suffix: string;
  positions: ChordDatabasePosition[];
}

export interface ChordDatabase {
  chords: Record<string, ChordDatabaseEntry[]>;
}

export interface ChordDatabaseSearch {
  datasetRoot: string;
  suffixCandidates: string[];
}

function getStringCount(position: ChordDatabasePosition) {
  return Array.isArray(position?.frets) ? position.frets.length : 6;
}

function getLowestPitchClass(position: ChordDatabasePosition) {
  if (!Array.isArray(position?.midi) || !position.midi.length) {
    return null;
  }

  const lowestMidi = position.midi[0];
  return ((lowestMidi % 12) + 12) % 12;
}

/** Lower is easier: low on the neck, few barres, a small span, open strings. */
function scorePosition(position: ChordDatabasePosition) {
  const frets = Array.isArray(position?.frets) ? position.frets : [];
  const openStringCount = frets.filter((fret) => fret === 0).length;
  const mutedStringCount = frets.filter((fret) => fret < 0).length;
  const frettedNotes = frets.filter((fret) => fret > 0);
  const fretSpan = frettedNotes.length
    ? Math.max(...frettedNotes) - Math.min(...frettedNotes)
    : 0;

  return (
    Math.max((position.baseFret || 1) - 1, 0) * 12 +
    (Array.isArray(position?.barres) ? position.barres.length : 0) * 3 +
    fretSpan * 2 +
    frettedNotes.length +
    mutedStringCount * 0.5 -
    openStringCount * 1.5
  );
}

/**
 * Easiest first; with a slash chord's bass pitch class, positions whose lowest
 * note is that bass come first.
 */
function rankChordPositions<T extends ChordDatabasePosition>(
  positions: T[],
  bassPitchClass?: number | null,
): T[] {
  if (!Array.isArray(positions) || !positions.length) {
    return [];
  }

  return positions
    .map((position, index) => ({
      bassMatches:
        typeof bassPitchClass === 'number'
          ? getLowestPitchClass(position) === bassPitchClass
          : false,
      index,
      position,
      score: scorePosition(position),
    }))
    .sort((left, right) => {
      if (left.bassMatches !== right.bassMatches) {
        return Number(right.bassMatches) - Number(left.bassMatches);
      }

      if (left.score !== right.score) {
        return left.score - right.score;
      }

      return left.index - right.index;
    })
    .map((entry) => entry.position);
}

function deriveBarres(position: ChordDatabasePosition) {
  const frets = Array.isArray(position?.frets) ? position.frets : [];
  const fingers = Array.isArray(position?.fingers) ? position.fingers : [];
  const barres = Array.isArray(position?.barres) ? position.barres : [];
  const stringCount = getStringCount(position);

  return barres
    .map((barreFret) => {
      const matchingEntries = frets
        .map((fret, index) => ({
          fret,
          index,
          finger: fingers[index] || 0,
        }))
        .filter((entry) => entry.fret === barreFret);

      if (!matchingEntries.length) {
        return null;
      }

      const targetFinger =
        matchingEntries.find((entry) => entry.finger > 0)?.finger || 0;
      const filteredEntries = targetFinger
        ? matchingEntries.filter((entry) => entry.finger === targetFinger)
        : matchingEntries;
      const fromIndex = filteredEntries[0]?.index;
      const toIndex = filteredEntries[filteredEntries.length - 1]?.index;

      if (
        typeof fromIndex !== 'number' ||
        typeof toIndex !== 'number' ||
        fromIndex === toIndex
      ) {
        return null;
      }

      const barreFinger = targetFinger > 0 ? String(targetFinger) : undefined;

      return {
        fromString: stringCount - fromIndex,
        toString: stringCount - toIndex,
        fret: barreFret,
        style: 'arc' as const,
        text: barreFinger,
      };
    })
    .filter((barre) => barre !== null);
}

/** SVGuitar's `{ fingers, barres, position }` for a position. */
function createSvguitarData(position: ChordDatabasePosition) {
  const fingers: [number, number | 'x', string?][] = [];
  const stringCount = getStringCount(position);

  for (const [index, fret] of (position?.frets || []).entries()) {
    const stringNumber = stringCount - index;
    const fingerNumber = position?.fingers?.[index] || 0;

    if (fret < 0) {
      fingers.push([stringNumber, 'x']);
      continue;
    }

    if (fret === 0) {
      fingers.push([stringNumber, 0]);
      continue;
    }

    fingers.push([
      stringNumber,
      fret,
      fingerNumber > 0 ? String(fingerNumber) : undefined,
    ]);
  }

  return {
    fingers,
    position: Math.max(position?.baseFret || 1, 1),
    barres: deriveBarres(position),
  };
}

/**
 * The database entry for the first suffix candidate it has. By default a chord
 * it has no suffix for falls back to the plain major entry (what the editor's
 * popup shows); `allowMajorFallback: false` returns `null` instead.
 */
function resolveMatchingChordEntry(
  database: ChordDatabase | null | undefined,
  search: ChordDatabaseSearch,
  { allowMajorFallback = true }: { allowMajorFallback?: boolean } = {},
): ChordDatabaseEntry | null {
  const chordEntries = database?.chords?.[search.datasetRoot];
  if (!Array.isArray(chordEntries) || !chordEntries.length) {
    return null;
  }

  for (const suffixCandidate of search.suffixCandidates) {
    const matchingEntry = chordEntries.find(
      (entry) => entry.suffix === suffixCandidate,
    );

    if (matchingEntry) {
      return matchingEntry;
    }
  }

  return allowMajorFallback
    ? chordEntries.find((entry) => entry.suffix === 'major') || null
    : null;
}

export {
  createSvguitarData,
  deriveBarres,
  getLowestPitchClass,
  rankChordPositions,
  resolveMatchingChordEntry,
  scorePosition,
};
