import {
  parseStrummingPatterns,
  parseStrummingPatternSteps,
} from '../OpenLyric/preview/helpers.ts';
import { isValidStrummingPatternValue } from '../../editor/scripts/shared.ts';

/**
 * Strum patterns in Open Lyric notation — the `Strumming Patterns` Config
 * field (`d--u-- | d-u---`), parsed by the notation's own parser
 * (`preview/helpers.ts`). One character is one sixteenth-note step; the
 * notation carries direction only, so each
 * stroke's loudness comes from where it falls in the bar
 * ({@link getStepVelocity}).
 */

export type StrumDirection = 'down' | 'up';

export interface StrumStep {
  direction: StrumDirection;
  /** Loudness, 0–1. */
  velocity: number;
}

/** What a page keeps and persists: the notation text is the source of truth. */
export interface StrumPatternDefinition {
  id: string;
  label: string;
  source: string;
}

export interface StrumPattern extends StrumPatternDefinition {
  /** Step `i` is the `i`-th character of the grid; `null` = rest. */
  steps: (StrumStep | null)[];
  /** The count printed under each step. */
  counts: string[];
  /** 0-based steps a `|` or space separator precedes. */
  groupBreaks: number[];
}

/** Loudness by position: bar downbeat, other beats, off-beats, the rest. */
export const STEP_VELOCITIES = {
  downbeat: 0.9,
  beat: 0.75,
  offbeat: 0.65,
  subdivision: 0.55,
} as const;

const EIGHTH_COUNTED_TIMES = new Set(['3/8', '6/8', '9/8', '12/8']);
const STRUMMING_PATTERNS_HEADER_RE = /^\s*-?\s*Strumming Patterns?\s*:\s*/i;
const OPEN_LYRIC_REST = '-';

export class StrumPatternError extends Error {}

export function getTimeSignatureParts(timeSignature: string): {
  beats: number;
  unit: number;
} {
  const [beats, unit] = String(timeSignature ?? '')
    .split('/')
    .map((part) => Number.parseInt(part, 10));

  return {
    beats: Number.isFinite(beats) && beats > 0 ? beats : 4,
    unit: Number.isFinite(unit) && unit > 0 ? unit : 4,
  };
}

function isEighthCounted(timeSignature: string) {
  return EIGHTH_COUNTED_TIMES.has(String(timeSignature).trim());
}

/**
 * Seconds from one step to the next. The tempo counts the time signature's
 * unit, and a step is always a sixteenth note: `unit / 16` of a beat.
 */
export function getStrumStepSeconds(tempo: number, timeSignature: string) {
  const { unit } = getTimeSignatureParts(timeSignature);

  return (60 / tempo) * (unit / 16);
}

/**
 * The count under step `index`, as the notation's preview prints it
 * (`getStrummingStepLabel` in `preview/helpers.ts`): `1 e & a` per beat, or
 * `1 &` per eighth in the eighth-counted times.
 */
export function getOpenLyricStepCount(
  index: number,
  timeSignature: string,
): string {
  if (isEighthCounted(timeSignature)) {
    return index % 2 === 0 ? String(Math.floor(index / 2) + 1) : '&';
  }

  const phase = index % 4;

  return phase === 0
    ? String(Math.floor(index / 4) + 1)
    : ['', 'e', '&', 'a'][phase];
}

/**
 * How loud a stroke on step `index` is. Sixteenth grid: the bar's first beat
 * is loudest, then the other beats, the `&`s, and the `e`/`a` sixteenths.
 * Eighth-counted times (steps counted `1 & 2 & …`, one number per eighth)
 * accent each dotted quarter — every third eighth, so every sixth step — then
 * the other eighths, and the `&` sixteenths between them the softest.
 */
export function getStepVelocity(index: number, timeSignature: string): number {
  const { beats } = getTimeSignatureParts(timeSignature);

  if (isEighthCounted(timeSignature)) {
    const barSteps = beats * 2;
    const inBar = index % barSteps;

    if (inBar === 0) {
      return STEP_VELOCITIES.downbeat;
    }

    if (inBar % 6 === 0) {
      return STEP_VELOCITIES.beat;
    }

    return inBar % 2 === 0
      ? STEP_VELOCITIES.offbeat
      : STEP_VELOCITIES.subdivision;
  }

  const inBar = index % (beats * 4);

  if (inBar === 0) {
    return STEP_VELOCITIES.downbeat;
  }

  switch (inBar % 4) {
    case 0:
      return STEP_VELOCITIES.beat;
    case 2:
      return STEP_VELOCITIES.offbeat;
    default:
      return STEP_VELOCITIES.subdivision;
  }
}

/** One Open Lyric pattern line, e.g. `d--u-- | d-u---`. */
export function parseOpenLyricPattern(
  definition: StrumPatternDefinition,
  timeSignature: string,
): StrumPattern {
  if (!isValidStrummingPatternValue(definition.source)) {
    throw new StrumPatternError(
      `"${definition.source}" is not an Open Lyric strumming pattern. Use d/D/v/V (down), u/U/^ (up), x/X/1/*/+ (alternating), -/_/./0 (rest) and | or spaces between groups.`,
    );
  }

  const parsedSteps = parseStrummingPatternSteps(definition.source);

  return {
    ...definition,
    steps: parsedSteps.map((step, index): StrumStep | null =>
      step.direction === 'down' || step.direction === 'up'
        ? {
            direction: step.direction,
            velocity: getStepVelocity(index, timeSignature),
          }
        : null,
    ),
    counts: parsedSteps.map((_, index) =>
      getOpenLyricStepCount(index, timeSignature),
    ),
    groupBreaks: parsedSteps
      .filter((step) => step.breakBefore)
      .map((step) => step.index),
  };
}

/**
 * Patterns typed or pasted in: the body of a `Strumming Patterns` field,
 * `// label` lines included, its `- Strumming Patterns:` header optional.
 */
export function readStrumPatternInput(
  text: string,
  createId: () => string,
  nextLabel: () => string,
): StrumPatternDefinition[] {
  const trimmed = String(text ?? '').trim();

  if (!trimmed) {
    throw new StrumPatternError('Type or paste a pattern first.');
  }

  const lines = trimmed
    .split(/\r?\n/)
    .map((line) => line.replace(STRUMMING_PATTERNS_HEADER_RE, ''));
  const patterns = parseStrummingPatterns(lines);

  if (!patterns.length) {
    throw new StrumPatternError('No pattern found — only comment lines.');
  }

  return patterns.map((pattern) => {
    const definition: StrumPatternDefinition = {
      id: createId(),
      label: pattern.labelSourceIndex == null ? nextLabel() : pattern.label,
      source: pattern.pattern,
    };

    parseOpenLyricPattern(definition, '4/4');
    return definition;
  });
}

/** The definition with step `index` cycled rest → down → up → rest. */
export function cycleStrumPatternStep(
  definition: StrumPatternDefinition,
  index: number,
  timeSignature: string,
): StrumPatternDefinition {
  const pattern = parseOpenLyricPattern(definition, timeSignature);
  const parsedStep = parseStrummingPatternSteps(definition.source)[index];

  if (!parsedStep) {
    return definition;
  }

  const direction = pattern.steps[index]?.direction;
  const nextCharacter =
    direction === 'down' ? 'u' : direction === 'up' ? OPEN_LYRIC_REST : 'd';

  return {
    ...definition,
    source: `${definition.source.slice(0, parsedStep.sourceOffset)}${nextCharacter}${definition.source.slice(parsedStep.sourceOffset + 1)}`,
  };
}
