import {
  getChordCardMidi,
  loadChordDatabases,
  resolveChordCard,
  type ChordCard,
  type ChordDatabases,
} from './chord-library.ts';
import {
  STRUM_INSTRUMENTS,
  getStrumInstrument,
  resolveStrumVoicing,
  type StrumInstrument,
  type StrumInstrumentId,
  type StrumVoicing,
} from './instruments.ts';
import {
  parseOpenLyricPattern,
  type StrumPattern,
  type StrumPatternDefinition,
} from './patterns.ts';
import {
  StrumPlayer,
  browserStrumPlayerRuntime,
  type StrumPlayerRuntime,
  type StrumPlayerState,
} from './StrumPlayer.ts';

/**
 * `OpenLyricPlayer` — the headless player: an Open Lyric song's strumming
 * patterns, and any chord Open Lyric can read, played on ten instruments —
 * acoustic, classical and electric guitar, piano, electric piano, organ,
 * ukulele, baritone ukulele, bass and upright bass. No DOM of its own;
 * `OpenLyricPlayerPlayground` is the UI built on it.
 *
 * It owns one {@link StrumPlayer} (one audio context, one soundfont cache) and
 * the chords-db tables the fretted voicings come from, loaded once on first
 * use. Every `play*` method must be called from a user gesture: the audio
 * context is unlocked before anything is awaited, as browsers require.
 */

export type OpenLyricPlayerState = StrumPlayerState;

export interface OpenLyricPlayerOptions {
  /** Browser seams (audio context, player + soundfont loaders); for tests. */
  runtime?: StrumPlayerRuntime;
}

export interface OpenLyricPlayerStateEvent {
  state: OpenLyricPlayerState;
  /** The pattern loading or playing; `null` when idle. */
  patternId: string | null;
  /** Set when a play failed (the player script or soundfont did not load). */
  error?: unknown;
}

export interface OpenLyricPlayerStepEvent {
  patternId: string;
  /** 1-based step of the pattern now sounding. */
  stepNumber: number;
}

export interface OpenLyricPlayerEventMap {
  state: OpenLyricPlayerStateEvent;
  step: OpenLyricPlayerStepEvent;
}

export interface OpenLyricPatternRequest {
  /**
   * The pattern: Open Lyric notation (`'d--u-- | d-u-d-'`), a
   * `{ id, label, source }` definition, or an already parsed pattern.
   */
  pattern: string | StrumPatternDefinition | StrumPattern;
  /** The song's key (`Config` → `Key`); a pattern strums its tonic chord. */
  key: string;
  /** Beats per minute, counting the time signature's unit. */
  tempo: number;
  /** Time signature (`Config` → `Time`). Default `4/4`. */
  time?: string;
  /** Default `guitar`. */
  instrument?: StrumInstrumentId;
}

const DEFAULT_TIME = '4/4';
const DEFAULT_INSTRUMENT: StrumInstrumentId = 'guitar';

function isParsedPattern(
  pattern: OpenLyricPatternRequest['pattern'],
): pattern is StrumPattern {
  return typeof pattern === 'object' && Array.isArray(pattern.steps);
}

export class OpenLyricPlayer {
  /** Every instrument, in display order. */
  static readonly instruments: readonly StrumInstrument[] = STRUM_INSTRUMENTS;

  #strum: StrumPlayer;
  #databases: ChordDatabases | null = null;
  #databaseLoad: Promise<ChordDatabases> | null = null;
  #listeners: {
    [K in keyof OpenLyricPlayerEventMap]: Set<
      (event: OpenLyricPlayerEventMap[K]) => void
    >;
  } = { state: new Set(), step: new Set() };

  constructor(options: OpenLyricPlayerOptions = {}) {
    this.#strum = new StrumPlayer(options.runtime ?? browserStrumPlayerRuntime);
    this.#strum.onStateChange = (state, patternId, error) =>
      this.#emit('state', { state, patternId, error });
    this.#strum.onStep = (patternId, stepNumber) =>
      this.#emit('step', { patternId, stepNumber });
  }

  get state(): OpenLyricPlayerState {
    return this.#strum.state;
  }

  /** The pattern loading or playing, if any. */
  get patternId(): string | null {
    return this.#strum.patternId;
  }

  /** Whether the chord tables have loaded — until then voicings are `null`. */
  get chordsLoaded(): boolean {
    return this.#databases !== null;
  }

  /** Subscribes to `state` or `step`; returns the unsubscribe. */
  on<K extends keyof OpenLyricPlayerEventMap>(
    type: K,
    listener: (event: OpenLyricPlayerEventMap[K]) => void,
  ): () => void {
    this.#listeners[type].add(listener);
    return () => {
      this.#listeners[type].delete(listener);
    };
  }

  /** Loads the chords-db tables once; every later call shares the load. */
  loadChords(): Promise<ChordDatabases> {
    if (!this.#databaseLoad) {
      const load = loadChordDatabases().then((databases) => {
        this.#databases = databases;
        return databases;
      });

      this.#databaseLoad = load;
      load.catch(() => {
        if (this.#databaseLoad === load) {
          this.#databaseLoad = null;
        }
      });
    }

    return this.#databaseLoad;
  }

  /**
   * The chord a pattern strums in `key` on `instrument` — the key's tonic
   * chord in that instrument's voicing. `null` when the key is unreadable,
   * the instrument has no voicing for it, or the chords have not loaded
   * ({@link loadChords}).
   */
  getVoicing(instrument: StrumInstrumentId, key: string): StrumVoicing | null {
    return this.#databases
      ? resolveStrumVoicing(instrument, key, this.#databases)
      : null;
  }

  /**
   * What `chord` looks like, and plays, on `instrument`: a chord diagram, piano
   * keys, or `none` with the reason. `null` until the chords have loaded.
   */
  resolveChord(instrument: StrumInstrumentId, chord: string): ChordCard | null {
    return this.#databases
      ? resolveChordCard(instrument, chord, this.#databases)
      : null;
  }

  /** Parses a pattern in Open Lyric notation against a time signature. */
  parsePattern(
    pattern: string | StrumPatternDefinition,
    time: string = DEFAULT_TIME,
  ): StrumPattern {
    const definition =
      typeof pattern === 'string'
        ? { id: 'pattern', label: 'Pattern', source: pattern }
        : pattern;

    return parseOpenLyricPattern(definition, time);
  }

  /**
   * Loads and decodes an instrument's soundfont ahead of a play. Creates the
   * audio context, so call it from a user gesture.
   */
  preload(instrument: StrumInstrumentId = DEFAULT_INSTRUMENT): Promise<void> {
    return this.#strum.preload(this.#getInstrument(instrument).soundfont);
  }

  /**
   * Stops whatever plays and loops `request.pattern` until {@link stop}.
   * Rejects when the pattern does not parse or there is nothing to strum (an
   * unreadable key, no voicing); a soundfont that fails to load is reported
   * through the `state` event instead, as `idle` with an `error`.
   */
  async playPattern(request: OpenLyricPatternRequest): Promise<void> {
    const time = request.time ?? DEFAULT_TIME;
    const instrument = this.#getInstrument(
      request.instrument ?? DEFAULT_INSTRUMENT,
    );
    const pattern = isParsedPattern(request.pattern)
      ? request.pattern
      : this.parsePattern(request.pattern, time);

    this.#strum.unlock();
    await this.loadChords();

    const voicing = this.getVoicing(instrument.id, request.key);

    if (!voicing) {
      throw new Error(
        `No ${instrument.label} voicing for the key of ${request.key}.`,
      );
    }

    await this.#strum.play({
      pattern,
      tempo: request.tempo,
      timeSignature: time,
      chord: voicing.midi,
      instrument: instrument.id,
    });
  }

  /**
   * Rolls `chord` once on `instrument`, alongside any playing pattern. Of
   * presses made while the soundfont loads only the last one plays: resolves
   * `true` once queued, `false` when a later press took over. Rejects when the
   * chord has nothing to play or the soundfont fails to load.
   */
  async playChord(
    chord: string,
    instrument: StrumInstrumentId = DEFAULT_INSTRUMENT,
  ): Promise<boolean> {
    const { label } = this.#getInstrument(instrument);

    this.#strum.unlock();

    const card = resolveChordCard(instrument, chord, await this.loadChords());
    const midi = getChordCardMidi(card);

    if (!midi.length) {
      throw new Error(
        card.kind === 'none' && card.reason === 'not-a-chord'
          ? `“${chord}” is not a chord Open Lyric can read.`
          : `No ${label} voicing for ${chord}.`,
      );
    }

    return this.#strum.playChord({ midi, instrument });
  }

  /** Swaps in an edited pattern mid-run; its next step plays the edit. */
  updatePattern(pattern: StrumPattern): void {
    this.#strum.updatePattern(pattern);
  }

  /**
   * Stops the pattern: a stroke under way finishes, then its ringing strings
   * are damped as a player's palm would. A chord roll rings on.
   */
  stop(): void {
    this.#strum.stop();
  }

  /** Drops every listener, then stops — silently. */
  destroy(): void {
    this.#listeners.state.clear();
    this.#listeners.step.clear();
    this.stop();
  }

  #getInstrument(id: StrumInstrumentId): StrumInstrument {
    const instrument = getStrumInstrument(id);

    if (!instrument) {
      throw new Error(`Unknown instrument “${id}”.`);
    }

    return instrument;
  }

  #emit<K extends keyof OpenLyricPlayerEventMap>(
    type: K,
    event: OpenLyricPlayerEventMap[K],
  ): void {
    for (const listener of this.#listeners[type]) {
      listener(event);
    }
  }
}
