import { SVGuitarChord } from 'svguitar';

import playerPluginCss from './OpenLyricPluginPlayer.scss?inline';
import { createPianoBoard } from './chord-figure.ts';
import { getChordCardMidi, type ChordCard } from './chord-library.ts';
import {
  OpenLyricPlayer,
  type OpenLyricPlayerStateEvent,
  type OpenLyricPlayerStepEvent,
} from './OpenLyricPlayer.ts';
import {
  getMidiNoteName,
  getStrumInstrument,
  type StrumInstrumentId,
} from './instruments.ts';
import type {
  OpenLyricChordPopupEventDetail,
  OpenLyricComponentHost,
  OpenLyricContributions,
  OpenLyricPlugin,
  OpenLyricRenderContext,
  OpenLyricStyleContribution,
  OpenLyricSurface,
} from '../../editor/components/index.ts';

/**
 * `OpenLyricPluginPlayer` — the strum player as a plugin for the two preview
 * components, `OpenLyric` (`lyric`) and `OpenLyricMarkdownManager`
 * (`markdown`):
 *
 * - every strumming-pattern card gets a play/stop button, and the step
 *   sounding is marked on the card while it plays;
 * - a click on a chord (a key note) rolls it, and so does the ▶ the chord
 *   popup gets; beside it, a view toggle shows the chord on the instrument
 *   (its diagram, or piano keys) in place of the popup's guitar diagram. A
 *   strumming-pattern reference's popup gets a ▶ that plays its pattern;
 * - the preview's settings popup gets an instrument picker
 *   (`contributes.settings`).
 *
 * Attach one instance per component. Every instance plays through one
 * `OpenLyricPlayer` shared by the page unless it is handed its own, so one
 * pattern sounds at a time across the embeds.
 */

export interface OpenLyricPluginPlayerOptions {
  /**
   * The instrument to play on until a reader picks another in the settings
   * popup, and what Reset returns to. Default `guitar`.
   */
  instrument?: StrumInstrumentId;
  /** The player to sound through. Default: one shared by the page. */
  player?: OpenLyricPlayer;
  /**
   * localStorage key remembering the instrument a reader picked. Default
   * `openLyricPluginPlayer.instrument`; `null` remembers nothing.
   */
  storageKey?: string | null;
}

type PatternState = 'idle' | 'loading' | 'playing';

/** A pattern card's play request, read off its data attributes. */
interface PatternCardRequest {
  id: string;
  /** The card's `data-pattern-index`. */
  index: string;
  label: string;
  source: string;
  key: string;
  tempo: number;
  time: string;
}

/** The chord popup's view toggle while it shows a chord of this plugin's. */
interface ChordView {
  chord: string;
  button: HTMLElement;
  panel: HTMLElement;
  /**
   * The view's frame in the panel, kept while it shows so the instrument
   * arrows survive a redraw: dropping the focused one would blur the popup,
   * and a blurred popup closes.
   */
  shell: {
    view: HTMLElement;
    caption: HTMLElement;
    figure: HTMLElement;
    notes: HTMLElement;
  } | null;
}

/** One component this plugin is attached to. */
interface Session {
  /** Prefix of the pattern ids this session plays. */
  uid: string;
  root: HTMLElement | null;
  /** Takes the root's listeners and observer back off. */
  unbindRoot: (() => void) | null;
  /**
   * The ▶ in the chord popup while it shows something of this session's —
   * with the pattern card's index when it is a pattern reference's.
   */
  popupButton: { button: HTMLElement; index: string | null } | null;
  /** The last pattern played here, and the instrument it sounds on. */
  request: (PatternCardRequest & { instrument: StrumInstrumentId }) | null;
  state: PatternState;
}

const PLUGIN_ID = 'player';
const DEFAULT_INSTRUMENT: StrumInstrumentId = 'guitar';
const DEFAULT_STORAGE_KEY = 'openLyricPluginPlayer.instrument';
/** What a pattern strums when the song has no `Key`. */
const DEFAULT_KEY = 'C';
/** The playground's default tempo, for a song without a `Tempo`. */
const DEFAULT_TEMPO = 70;
const MIN_TEMPO = 20;
const MAX_TEMPO = 300;
const DEFAULT_TIME = '4/4';

/** The marker exports strip (`readExportMarkup` in the core). */
const PLUGIN_UI_ATTRIBUTE = 'data-ol-plugin-ui';
/** Scopes this plugin's stylesheet to a render root it decorates. */
const ROOT_MARKER_ATTRIBUTE = 'data-ol-player';
const CARD_STATE_ATTRIBUTE = 'data-olpp-state';
const STEP_ATTRIBUTE = 'data-olpp-step';
/** How `PluginHost` marks the style nodes it installs for a plugin. */
const PLUGIN_STYLE_MARKER = 'data-open-lyric-plugin-id';

const PATTERN_CARD_SELECTOR = '[data-pattern-source][data-pattern-index]';
const CHORD_SELECTOR = '[data-chord-key]';
/** `OPEN_LYRIC_CHORD_POPUP_EVENT` in the core: the chord popup opening. */
const CHORD_POPUP_EVENT = 'open-lyric:chord-popup';
const PLAY_BUTTON_SELECTOR = `.olpp-play[${PLUGIN_UI_ATTRIBUTE}="${PLUGIN_ID}"]`;
const STEP_ROW_SELECTOR =
  '.ol-song-view__pattern-row--stroke, .ol-song-view__pattern-row--count';

/** The zero-width separators a Khmer document may put between groups. */
const INVISIBLE_SEPARATOR_RE = /[\u200B-\u200D\u2060\uFEFF]/g;

const VIEW_ICON =
  '<svg class="olpp-view-toggle__icon" viewBox="0 0 24 24" aria-hidden="true"><path d="M2 12s3.6-6.5 10-6.5S22 12 22 12s-3.6 6.5-10 6.5S2 12 2 12z" fill="none" stroke="currentColor" stroke-width="2.2"/><circle cx="12" cy="12" r="3.2" fill="currentColor"/></svg>';

/**
 * Inlined (`?inline`) rather than contributed as an `href`, so the sheet
 * travels inside the bundle and needs no second request.
 *
 * A `<link href>` pointing at an emitted `.css` asset is the one thing that
 * cannot be relied on here: a Vite dev host serves a `.css` under
 * `node_modules` as a JavaScript HMR module (`Content-Type: text/javascript`),
 * and a browser refuses a stylesheet whose MIME is not `text/css` — so every
 * control this sheet styles, the chord popup's ▶ among them, rendered as a
 * bare unstyled `<button>`. `cssText` has no MIME to get wrong.
 */
const PLAYER_STYLE: OpenLyricStyleContribution = { cssText: playerPluginCss };

let sharedPlayer: OpenLyricPlayer | null = null;
let sessionCount = 0;
let fieldCount = 0;

function getSharedPlayer(): OpenLyricPlayer {
  sharedPlayer ??= new OpenLyricPlayer();
  return sharedPlayer;
}

function isInstrumentId(value: unknown): value is StrumInstrumentId {
  return (
    typeof value === 'string' && Boolean(getStrumInstrument(value as never))
  );
}

function readTempo(text: string | undefined): number {
  const match = String(text ?? '').match(/\d+(?:\.\d+)?/);
  const tempo = match ? Math.round(Number(match[0])) : Number.NaN;
  return Number.isFinite(tempo) && tempo > 0
    ? Math.min(MAX_TEMPO, Math.max(MIN_TEMPO, tempo))
    : DEFAULT_TEMPO;
}

function readPatternCard(card: HTMLElement, uid: string): PatternCardRequest {
  const index = card.dataset['patternIndex'] ?? '';
  const number = Number.parseInt(index, 10) + 1;
  const numberText = Number.isFinite(number) ? `#${number}` : '';
  const label = (card.dataset['patternLabel'] ?? '').trim();

  return {
    id: `${uid}:${index}`,
    index,
    label:
      label && label !== `Pattern ${numberText}`
        ? `${numberText} ${label}`.trim()
        : `Pattern ${numberText}`.trim(),
    source: (card.dataset['patternSource'] ?? '')
      .replace(INVISIBLE_SEPARATOR_RE, ' ')
      .trim(),
    key: (card.dataset['patternPreviewKey'] ?? '').trim() || DEFAULT_KEY,
    tempo: readTempo(card.dataset['patternPreviewTempo']),
    time: (card.dataset['patternPreviewTime'] ?? '').trim() || DEFAULT_TIME,
  };
}

function findPatternCards(root: ParentNode): HTMLElement[] {
  return Array.from(root.querySelectorAll<HTMLElement>(PATTERN_CARD_SELECTOR));
}

function findPatternCard(root: ParentNode, index: string): HTMLElement | null {
  return (
    findPatternCards(root).find(
      (card) => card.dataset['patternIndex'] === index,
    ) ?? null
  );
}

function clearSteps(scope: ParentNode): void {
  for (const cell of Array.from(
    scope.querySelectorAll(`[${STEP_ATTRIBUTE}]`),
  )) {
    cell.removeAttribute(STEP_ATTRIBUTE);
  }
}

export class OpenLyricPluginPlayer implements OpenLyricPlugin {
  readonly id = PLUGIN_ID;
  readonly apiVersion = 1 as const;
  readonly surfaces: readonly OpenLyricSurface[] = ['lyric', 'markdown'];
  readonly contributes: OpenLyricContributions;

  /**
   * Put the plugin's stylesheet in `document.head` for the page's lifetime,
   * without attaching the plugin — the page-level counterpart of the sheet an
   * attached plugin installs into its component. Idempotent. The sheet only
   * styles render roots the plugin has marked, so it changes nothing on a page
   * that never attaches it.
   */
  static installShellStyle(): void {
    const head = globalThis.document?.head;
    if (!head || !PLAYER_STYLE.cssText) {
      return;
    }
    // One sheet per page: the marker alone identifies it, the stylesheet
    // being inline now rather than an href to compare.
    if (head.querySelector(`style[${PLUGIN_STYLE_MARKER}="${PLUGIN_ID}"]`)) {
      return;
    }
    const style = Object.assign(document.createElement('style'), {
      textContent: PLAYER_STYLE.cssText,
    });
    style.setAttribute(PLUGIN_STYLE_MARKER, PLUGIN_ID);
    head.append(style);
  }

  #player: OpenLyricPlayer | null;
  #playerUnsubscribes: Array<() => void> = [];
  #defaultInstrument: StrumInstrumentId;
  #instrument: StrumInstrumentId;
  #storageKey: string | null;
  #sessions = new Map<OpenLyricComponentHost, Session>();
  #instrumentSelects = new Set<HTMLSelectElement>();
  /** Whether the chord popup shows the instrument view; kept across popups. */
  #chordViewOpen = false;
  #chordView: ChordView | null = null;

  constructor(options: OpenLyricPluginPlayerOptions = {}) {
    if (
      options.instrument !== undefined &&
      !isInstrumentId(options.instrument)
    ) {
      throw new Error(`Unknown instrument “${String(options.instrument)}”.`);
    }
    this.#defaultInstrument = options.instrument ?? DEFAULT_INSTRUMENT;
    this.#storageKey =
      options.storageKey === undefined
        ? DEFAULT_STORAGE_KEY
        : options.storageKey;
    // A reader's saved pick outranks the host's configured instrument.
    this.#instrument = this.#readStoredInstrument() ?? this.#defaultInstrument;
    this.#player = options.player ?? null;
    this.contributes = {
      style: [PLAYER_STYLE],
      settings: [
        {
          render: (mount) => this.#renderInstrumentField(mount),
          reset: () => this.resetInstrument(),
        },
      ],
    };
    // `contributes.style` alone is not enough for this plugin, and the reason
    // is structural rather than a timing accident: the chord popup is appended
    // to `document.body` by the core, NOT into the component container that a
    // scoped contribution installs into. A host that never calls
    // `installShellStyle()` therefore got a popup ▶ with no rules reaching it —
    // a bare unstyled <button>, 16×6 px, its triangle missing because the icon
    // is drawn entirely in CSS. So the plugin installs its own page-level sheet
    // instead of relying on the host to remember. It is idempotent, and safe to
    // install unasked for the same reason `installShellStyle` is: every rule is
    // scoped under markup only this plugin writes, so a page that ends up
    // attaching nothing is unchanged by it.
    OpenLyricPluginPlayer.installShellStyle();
  }

  /** The player patterns and chords sound through. */
  get player(): OpenLyricPlayer {
    this.#player ??= getSharedPlayer();
    return this.#player;
  }

  /** The instrument patterns and chords play on. */
  get instrument(): StrumInstrumentId {
    return this.#instrument;
  }

  /**
   * Switch instruments: remembered, reflected in every settings popup showing
   * the picker, and a pattern playing here restarts on the new one.
   */
  set instrument(next: StrumInstrumentId) {
    if (!isInstrumentId(next)) {
      throw new Error(`Unknown instrument “${String(next)}”.`);
    }
    this.#writeStoredInstrument(next);
    this.#applyInstrument(next);
  }

  /** Back to the configured instrument, forgetting the reader's pick. */
  resetInstrument(): void {
    this.#writeStoredInstrument(null);
    this.#applyInstrument(this.#defaultInstrument);
  }

  /** Stop a pattern this plugin started, wherever it plays. */
  stop(): void {
    for (const session of this.#sessions.values()) {
      this.#stopSession(session);
    }
  }

  /* ------------------------------ lifecycle ------------------------------ */

  install(host: OpenLyricComponentHost): void {
    this.#session(host);
  }

  uninstall(host: OpenLyricComponentHost): void {
    const session = this.#sessions.get(host);
    if (session) {
      this.#detachSession(session);
      this.#sessions.delete(host);
    }
    if (!this.#sessions.size) {
      for (const off of this.#playerUnsubscribes.splice(0)) {
        off();
      }
    }
  }

  /**
   * Attached to a preview that is already mounted, nothing has rendered with
   * this plugin yet — render once so the cards get their buttons.
   */
  onMount(host: OpenLyricComponentHost): void {
    if (!this.#session(host).root) {
      (host as Partial<{ reload(): void }>).reload?.();
    }
  }

  onUnmount(host: OpenLyricComponentHost): void {
    const session = this.#sessions.get(host);
    if (session) {
      this.#detachSession(session);
    }
  }

  onAfterRender(
    host: OpenLyricComponentHost,
    context: OpenLyricRenderContext,
  ): void {
    const session = this.#session(host);
    const root = context.root;

    if (session.root !== root) {
      session.unbindRoot?.();
      session.root = root;
      session.unbindRoot = this.#bindRoot(session, root);
    }
    this.#decorate(session);
  }

  /* ------------------------------- sessions ------------------------------ */

  #session(host: OpenLyricComponentHost): Session {
    let session = this.#sessions.get(host);
    if (!session) {
      sessionCount += 1;
      session = {
        uid: `olpp-${sessionCount}`,
        root: null,
        unbindRoot: null,
        popupButton: null,
        request: null,
        state: 'idle',
      };
      this.#sessions.set(host, session);
    }
    return session;
  }

  /** Stop the session's pattern and take everything added back off its root. */
  #detachSession(session: Session): void {
    this.#stopSession(session);
    session.unbindRoot?.();
    session.unbindRoot = null;
    session.popupButton?.button.remove();
    session.popupButton = null;

    const root = session.root;
    if (root) {
      root.removeAttribute(ROOT_MARKER_ATTRIBUTE);
      for (const button of Array.from(
        root.querySelectorAll(PLAY_BUTTON_SELECTOR),
      )) {
        button.remove();
      }
      for (const card of Array.from(
        root.querySelectorAll(`[${CARD_STATE_ATTRIBUTE}]`),
      )) {
        card.removeAttribute(CARD_STATE_ATTRIBUTE);
      }
      clearSteps(root);
    }
    session.root = null;
  }

  #stopSession(session: Session): void {
    // Forgetting the request also cancels a play still loading for it: when
    // it starts, `#handleState` finds it stale and stops it.
    session.request = null;
    if (session.state === 'idle') {
      return;
    }
    session.state = 'idle';
    if (this.#ownsPattern(session, this.#player?.patternId)) {
      this.#player?.stop();
    }
    this.#paint(session);
  }

  #ownsPattern(session: Session, patternId: string | null | undefined) {
    return Boolean(patternId?.startsWith(`${session.uid}:`));
  }

  /**
   * After a re-render: keep a playing pattern in step with its card. An edited
   * pattern swaps in mid-run; a changed key, tempo or time restarts it; a card
   * that is gone stops it.
   */
  #followRender(session: Session): void {
    const request = session.request;
    if (session.state === 'idle' || !request || !session.root) {
      return;
    }

    const card = findPatternCard(session.root, request.index);
    if (!card) {
      this.#stopSession(session);
      return;
    }

    const next = readPatternCard(card, session.uid);
    if (
      next.key !== request.key ||
      next.tempo !== request.tempo ||
      next.time !== request.time
    ) {
      this.#playCard(session, card);
      return;
    }
    if (next.source !== request.source) {
      try {
        this.player.updatePattern(
          this.player.parsePattern(
            { id: next.id, label: next.label, source: next.source },
            next.time,
          ),
        );
        session.request = { ...request, ...next };
      } catch {
        this.#stopSession(session);
      }
    }
  }

  /* -------------------------------- player ------------------------------- */

  #ensurePlayer(): OpenLyricPlayer {
    const player = this.player;
    if (!this.#playerUnsubscribes.length) {
      this.#playerUnsubscribes.push(
        player.on('state', (event) => this.#handleState(event)),
        player.on('step', (event) => this.#handleStep(event)),
      );
    }
    return player;
  }

  #handleState({ state, patternId, error }: OpenLyricPlayerStateEvent): void {
    let isStale = false;
    for (const session of this.#sessions.values()) {
      const previous = session.state;
      const isOwn = this.#ownsPattern(session, patternId);
      if (state !== 'idle' && isOwn && patternId !== session.request?.id) {
        // A play this session has since stopped or replaced, starting late
        // (its chord tables were still loading): silenced below.
        isStale = true;
        continue;
      }
      if (state !== 'idle' && isOwn) {
        session.state = state;
      } else {
        // Anything else ends this session's pattern: a stop, a failed load, or
        // another pattern taking over the player. The stop inside a new play
        // lands here too, and that play's own `loading` follows at once.
        if (error && previous === 'loading') {
          console.error('Open Lyric player failed to load a sound.', error);
        }
        session.state = 'idle';
      }
      if (session.state !== previous) {
        this.#paint(session);
      }
    }
    if (isStale) {
      this.#player?.stop();
    }
  }

  #handleStep({ patternId, stepNumber }: OpenLyricPlayerStepEvent): void {
    for (const session of this.#sessions.values()) {
      const request = session.request;
      if (!request || request.id !== patternId || !session.root) {
        continue;
      }
      const card = findPatternCard(session.root, request.index);
      if (!card) {
        continue;
      }
      clearSteps(card);
      for (const row of Array.from(card.querySelectorAll(STEP_ROW_SELECTOR))) {
        row.children[stepNumber - 1]?.setAttribute(STEP_ATTRIBUTE, '');
      }
    }
  }

  #togglePattern(session: Session, card: HTMLElement): void {
    const index = card.dataset['patternIndex'] ?? '';
    if (session.state !== 'idle' && session.request?.index === index) {
      this.#stopSession(session);
      return;
    }
    this.#playCard(session, card);
  }

  /** Play the card's pattern — straight from the click, as audio requires. */
  #playCard(session: Session, card: HTMLElement): void {
    const request = {
      ...readPatternCard(card, session.uid),
      instrument: this.#instrument,
    };
    const player = this.#ensurePlayer();

    session.request = request;
    session.state = 'loading';
    this.#paint(session);

    player
      .playPattern({
        pattern: {
          id: request.id,
          label: request.label,
          source: request.source,
        },
        key: request.key,
        tempo: request.tempo,
        time: request.time,
        instrument: request.instrument,
      })
      .catch((error: unknown) => {
        if (session.request === request && session.state !== 'idle') {
          session.state = 'idle';
          this.#paint(session);
        }
        console.error(
          `Open Lyric player could not play ${request.label}.`,
          error,
        );
      });
  }

  #playChord(chord: string): void {
    this.#ensurePlayer()
      .playChord(chord, this.#instrument)
      .catch((error: unknown) => {
        console.warn(`Open Lyric player could not play “${chord}”.`, error);
      });
  }

  #applyInstrument(next: StrumInstrumentId): void {
    for (const select of this.#instrumentSelects) {
      select.value = next;
    }
    if (next === this.#instrument) {
      return;
    }
    this.#instrument = next;
    this.#renderChordView();

    for (const session of this.#sessions.values()) {
      const card =
        session.state !== 'idle' && session.request && session.root
          ? findPatternCard(session.root, session.request.index)
          : null;
      if (card) {
        this.#playCard(session, card);
      } else {
        // The idle buttons name the instrument too.
        this.#paint(session);
      }
    }
  }

  /* --------------------------------- DOM --------------------------------- */

  /**
   * Give every pattern card on the root its button and mirror the playing
   * state onto it. Runs after each render, and whenever the root's content
   * changes without one: an app page's incremental fast path patches the
   * panel itself.
   */
  #decorate(session: Session): void {
    const root = session.root;
    if (!root) {
      return;
    }
    root.setAttribute(ROOT_MARKER_ATTRIBUTE, '');
    for (const card of findPatternCards(root)) {
      if (!card.querySelector(PLAY_BUTTON_SELECTOR)) {
        this.#addPlayButton(session, card);
      }
    }
    this.#followRender(session);
    this.#paint(session);
  }

  #createPlayButton(onPress: () => void): HTMLButtonElement {
    const button = document.createElement('button');
    button.type = 'button';
    button.className = 'olpp-play';
    button.setAttribute(PLUGIN_UI_ATTRIBUTE, PLUGIN_ID);
    button.dataset['state'] = 'idle';
    button.innerHTML =
      '<span class="olpp-play__icon" aria-hidden="true"></span>';
    button.addEventListener('click', (event) => {
      event.preventDefault();
      // The card itself can be a host's click target (the markdown panel
      // jumps to the pattern's source line); a press here only plays.
      event.stopPropagation();
      onPress();
    });
    return button;
  }

  #addPlayButton(session: Session, card: HTMLElement): void {
    const button = this.#createPlayButton(() =>
      this.#togglePattern(session, card),
    );
    const slot =
      card.querySelector('.ol-song-view__pattern-heading') ??
      card.querySelector('.ol-song-view__pattern-header') ??
      card;
    slot.prepend(button);
  }

  /** Chord clicks, the chord popup opening, and content swapped in. */
  #bindRoot(session: Session, root: HTMLElement): () => void {
    const onClick = (event: Event) => {
      const target = event.target instanceof Element ? event.target : null;
      const chord = target?.closest<HTMLElement>(CHORD_SELECTOR);
      if (!chord || !root.contains(chord)) {
        return;
      }
      const name = (chord.getAttribute('data-chord-key') ?? '').trim();
      if (name) {
        this.#playChord(name);
      }
    };
    const onPopup = (event: Event) => this.#fillPopupActions(session, event);
    const observer =
      typeof MutationObserver === 'function'
        ? new MutationObserver(() => this.#decorate(session))
        : null;

    root.addEventListener('click', onClick);
    root.addEventListener(CHORD_POPUP_EVENT, onPopup);
    observer?.observe(root, { childList: true, subtree: true });
    return () => {
      root.removeEventListener('click', onClick);
      root.removeEventListener(CHORD_POPUP_EVENT, onPopup);
      observer?.disconnect();
    };
  }

  /**
   * The chord popup opened for something in this preview: put a ▶ in its
   * header. A chord's rolls the chord; a pattern reference's plays or stops
   * the pattern of the card it refers to.
   */
  #fillPopupActions(session: Session, event: Event): void {
    const detail = (event as CustomEvent<OpenLyricChordPopupEventDetail>)
      .detail;
    const trigger = event.target instanceof Element ? event.target : null;
    if (!detail?.actions || !trigger) {
      return;
    }

    if (detail.kind === 'chord') {
      const chord = detail.text;
      const button = this.#createPlayButton(() => this.#playChord(chord));
      const text = `Play ${chord} on ${this.#instrumentLabel()}`;
      button.setAttribute('aria-label', text);
      button.title = text;
      session.popupButton = { button, index: null };
      detail.actions.append(button);
      // An older core's popup has no panel to show the view in.
      if (detail.panel) {
        detail.actions.append(this.#createViewToggle(chord, detail.panel));
        this.#renderChordView();
      }
      return;
    }

    const reference = Number.parseInt(
      trigger.getAttribute('data-pattern-reference-index') ?? '',
      10,
    );
    const index = String(reference - 1);
    if (!session.root || !findPatternCard(session.root, index)) {
      return;
    }
    const button = this.#createPlayButton(() => {
      const card = session.root ? findPatternCard(session.root, index) : null;
      if (card) {
        this.#togglePattern(session, card);
      }
    });
    session.popupButton = { button, index };
    detail.actions.append(button);
    this.#paint(session);
  }

  /**
   * Mirror the session's state onto its cards, their buttons, and a pattern
   * reference's ▶ in the chord popup.
   */
  #paint(session: Session): void {
    const root = session.root;
    if (!root) {
      return;
    }

    for (const card of findPatternCards(root)) {
      const index = card.dataset['patternIndex'] ?? '';
      const state: PatternState =
        session.request?.index === index ? session.state : 'idle';
      const label = readPatternCard(card, session.uid).label;

      if (state === 'idle') {
        card.removeAttribute(CARD_STATE_ATTRIBUTE);
      } else {
        card.setAttribute(CARD_STATE_ATTRIBUTE, state);
      }
      if (state !== 'playing') {
        clearSteps(card);
      }

      const button = card.querySelector<HTMLElement>(PLAY_BUTTON_SELECTOR);
      if (button) {
        this.#paintButton(button, state, label);
      }
      if (session.popupButton?.index === index) {
        this.#paintButton(session.popupButton.button, state, label);
      }
    }
  }

  #paintButton(button: HTMLElement, state: PatternState, label: string) {
    const text =
      state === 'idle'
        ? `Play ${label} on ${this.#instrumentLabel()}`
        : `Stop ${label}`;
    button.dataset['state'] = state;
    button.setAttribute('aria-pressed', String(state !== 'idle'));
    button.setAttribute('aria-label', text);
    button.title = text;
  }

  #instrumentLabel(): string {
    return getStrumInstrument(this.#instrument)?.label ?? this.#instrument;
  }

  /* ----------------------------- chord view ------------------------------ */

  /**
   * The chord popup's view toggle, beside its ▶: shows the chord on the
   * instrument in the popup's panel. It stays on for the next chord until
   * pressed again.
   */
  #createViewToggle(chord: string, panel: HTMLElement): HTMLButtonElement {
    const button = document.createElement('button');
    button.type = 'button';
    button.className = 'olpp-view-toggle';
    button.setAttribute(PLUGIN_UI_ATTRIBUTE, PLUGIN_ID);
    button.innerHTML = VIEW_ICON;
    button.addEventListener('click', (event) => {
      event.preventDefault();
      event.stopPropagation();
      this.#chordViewOpen = !this.#chordViewOpen;
      this.#renderChordView();
    });
    this.#chordView = { chord, button, panel, shell: null };
    return button;
  }

  /** Mirror the toggle onto the popup open for one of this plugin's chords. */
  #renderChordView(): void {
    const view = this.#chordView;
    if (!view) {
      return;
    }
    if (!view.button.isConnected) {
      // The popup has moved on (or closed) since.
      this.#chordView = null;
      return;
    }
    const { chord, button, panel } = view;
    const text = this.#chordViewOpen
      ? `Back to the guitar diagram for ${chord}`
      : `Show ${chord} on ${this.#instrumentLabel()}`;
    button.setAttribute('aria-pressed', String(this.#chordViewOpen));
    button.setAttribute('aria-label', text);
    button.title = text;

    if (!this.#chordViewOpen) {
      view.shell = null;
      panel.replaceChildren();
      panel.hidden = true;
      return;
    }

    const card = this.player.resolveChord(this.#instrument, chord);
    if (card) {
      this.#drawChordView(card, view);
      return;
    }

    // The chord tables load on first use.
    view.shell = null;
    panel.replaceChildren(this.#createViewMessage('Loading…'));
    panel.hidden = false;
    this.player.loadChords().then(
      () => {
        if (this.#chordView === view) {
          this.#renderChordView();
        }
      },
      (error: unknown) => {
        if (this.#chordView === view) {
          panel.replaceChildren(
            this.#createViewMessage('Unable to load the chord voicings.'),
          );
        }
        console.error('Open Lyric player could not load its chords.', error);
      },
    );
  }

  /** The view's frame: the instrument between its ‹ › arrows, then the figure. */
  #createViewShell(): NonNullable<ChordView['shell']> {
    const view = document.createElement('div');
    view.className = 'olpp-view';

    const switcher = document.createElement('div');
    switcher.className = 'olpp-view__switcher';

    const caption = document.createElement('p');
    caption.className = 'olpp-view__caption';
    caption.setAttribute('aria-live', 'polite');

    const arrow = (step: -1 | 1) => {
      const button = document.createElement('button');
      button.type = 'button';
      button.className = `olpp-view__arrow olpp-view__arrow--${step < 0 ? 'previous' : 'next'}`;
      button.setAttribute(PLUGIN_UI_ATTRIBUTE, PLUGIN_ID);
      button.setAttribute(
        'aria-label',
        step < 0 ? 'Previous instrument' : 'Next instrument',
      );
      button.title = button.getAttribute('aria-label')!;
      button.innerHTML = `<svg viewBox="0 0 24 24" aria-hidden="true"><path d="${step < 0 ? 'M15 5l-7 7 7 7' : 'M9 5l7 7-7 7'}" fill="none" stroke="currentColor" stroke-width="2.6" stroke-linecap="round" stroke-linejoin="round"/></svg>`;
      button.addEventListener('click', (event) => {
        event.preventDefault();
        event.stopPropagation();
        this.#stepInstrument(step);
      });
      return button;
    };

    const figure = document.createElement('div');
    figure.className = 'olpp-view__figure';

    const notes = document.createElement('p');
    notes.className = 'olpp-view__notes';

    switcher.append(arrow(-1), caption, arrow(1));
    view.append(switcher, figure, notes);
    return { view, caption, figure, notes };
  }

  /** Switch to the instrument before or after this one, wrapping around. */
  #stepInstrument(step: -1 | 1): void {
    const ids = OpenLyricPlayer.instruments.map((instrument) => instrument.id);
    const index = ids.indexOf(this.#instrument);
    this.instrument = ids[(index + step + ids.length) % ids.length]!;
  }

  #drawChordView(card: ChordCard, chordView: ChordView): void {
    const { panel } = chordView;
    const instrument = this.#instrumentLabel();
    const chord = card.chord;
    const midi = getChordCardMidi(card);

    if (!chordView.shell?.view.isConnected) {
      chordView.shell = this.#createViewShell();
      panel.replaceChildren(chordView.shell.view);
    }
    const { view, caption, figure, notes } = chordView.shell;
    view.dataset['kind'] = card.kind;
    caption.textContent = instrument;
    figure.replaceChildren();
    notes.textContent = midi
      .map((note) => getMidiNoteName(note, chord).replace(/-?\d+$/, ''))
      .join(' ');
    notes.hidden = !midi.length;

    // Shown before drawing: SVGuitar measures its text as it draws.
    panel.hidden = false;

    if (card.kind === 'piano') {
      figure.append(createPianoBoard(chord, card.piano, chord));
      return;
    }
    if (card.kind === 'none') {
      figure.append(
        this.#createViewMessage(
          card.reason === 'not-a-chord'
            ? `“${chord}” can’t be read as a chord.`
            : `No ${instrument} voicing for ${chord}.`,
        ),
      );
      return;
    }

    // The popup's own diagram colours, read where the popup's theme applies.
    const token = (name: string, fallback: string) =>
      getComputedStyle(panel).getPropertyValue(name).trim() || fallback;
    try {
      new SVGuitarChord(figure)
        .configure({
          ...card.chart.settings,
          title: '',
          titleBottomMargin: 0,
          backgroundColor: 'transparent',
          color: token('--chord-popup-diagram-ink', '#213547'),
          fretColor: token('--chord-popup-diagram-line', '#52606d'),
          stringColor: token('--chord-popup-diagram-line', '#52606d'),
          fretLabelColor: token('--chord-popup-diagram-label', '#52606d'),
          tuningsColor: token('--chord-popup-diagram-label', '#52606d'),
          fingerColor: token('--accent', '#115e59'),
          fingerStrokeColor: token('--accent', '#115e59'),
          fingerTextColor: token('--surface', '#ffffff'),
          svgTitle: `${instrument} diagram for ${chord}`,
        })
        .chord(card.chart.chord)
        .draw();
    } catch (error) {
      figure.replaceChildren(
        this.#createViewMessage('Unable to draw the diagram.'),
      );
      console.error(`Open Lyric player could not draw ${chord}.`, error);
    }
  }

  #createViewMessage(text: string): HTMLElement {
    const message = document.createElement('p');
    message.className = 'olpp-view__message';
    message.textContent = text;
    return message;
  }

  /* ------------------------------- settings ------------------------------ */

  #renderInstrumentField(mount: HTMLElement): () => void {
    fieldCount += 1;
    const id = `olpp-instrument-${fieldCount}`;

    const label = document.createElement('label');
    label.className = 'topbar-settings__label';
    label.htmlFor = id;
    label.textContent = 'Instrument';

    const select = document.createElement('select');
    select.id = id;
    select.className = 'topbar-settings__text-input';
    for (const instrument of OpenLyricPlayer.instruments) {
      select.append(new Option(instrument.label, instrument.id));
    }
    select.value = this.#instrument;

    const note = document.createElement('p');
    note.className = 'topbar-settings__field-note';
    note.textContent = 'Plays a chord you click and a strumming pattern’s ▶.';

    const onChange = () => {
      if (isInstrumentId(select.value)) {
        this.instrument = select.value;
      }
    };
    select.addEventListener('change', onChange);
    this.#instrumentSelects.add(select);
    mount.append(label, select, note);

    return () => {
      select.removeEventListener('change', onChange);
      this.#instrumentSelects.delete(select);
    };
  }

  #readStoredInstrument(): StrumInstrumentId | null {
    if (!this.#storageKey) {
      return null;
    }
    try {
      const stored = globalThis.localStorage?.getItem(this.#storageKey);
      return isInstrumentId(stored) ? stored : null;
    } catch {
      return null;
    }
  }

  #writeStoredInstrument(instrument: StrumInstrumentId | null): void {
    if (!this.#storageKey) {
      return;
    }
    try {
      if (instrument) {
        globalThis.localStorage?.setItem(this.#storageKey, instrument);
      } else {
        globalThis.localStorage?.removeItem(this.#storageKey);
      }
    } catch {
      // Storage unavailable (private mode, a sandbox): the pick lasts the page.
    }
  }
}
