const SHARP_NAMES = [
  'C',
  'C#',
  'D',
  'D#',
  'E',
  'F',
  'F#',
  'G',
  'G#',
  'A',
  'A#',
  'B',
];
const FLAT_NAMES = [
  'C',
  'Db',
  'D',
  'Eb',
  'E',
  'F',
  'Gb',
  'G',
  'Ab',
  'A',
  'Bb',
  'B',
];

export function getStrumInstrument(id: string): StrumInstrument | null {
  return STRUM_INSTRUMENTS.find((instrument) => instrument.id === id) ?? null;
}

/**
 * The chord a pattern strums on `instrumentId` in `keyText` — the key's
 * tonic chord (`E`, `C#m`) — or `null` when the key is unreadable or the
 * instrument has no voicing for it.
 */
export function resolveStrumVoicing(
  instrumentId: StrumInstrumentId,
  keyText: string,
  databases: ChordDatabases,
): StrumVoicing | null {
  const key = parseMainKey(keyText);

  if (!key) {
    return null;
  }

  const card = resolveChordCard(instrumentId, key.raw, databases);
  const midi = getChordCardMidi(card);

  return midi.length ? { chord: key.raw, midi, card } : null;
}

/** `56` → `G#3`, or `Ab3` in a key written with flats. */
export function getMidiNoteName(midi: number, keyText = ''): string {
  const names =
    (parseMainKey(keyText)?.alteration ?? 0) < 0 ? FLAT_NAMES : SHARP_NAMES;

  return `${names[((midi % 12) + 12) % 12]}${Math.floor(midi / 12) - 1}`;
}
