import playgroundCss from './OpenLyricPlayerPlayground.scss?inline';
import {
  CONFIG_ENUM_FIELD_VALUES,
  CONFIG_KEY_VALUES,
} from '../../editor/scripts/shared.ts';
import {
  STRUM_INSTRUMENTS,
  getMidiNoteName,
  getStrumInstrument,
  type StrumInstrument,
  type StrumInstrumentId,
  type StrumVoicing,
} from './instruments.ts';
import {
  OpenLyricPlayer,
  type OpenLyricPlayerStateEvent,
} from './OpenLyricPlayer.ts';
import {
  cycleStrumPatternStep,
  parseOpenLyricPattern,
  readStrumPatternInput,
  type StrumPattern,
  type StrumPatternDefinition,
  type StrumStep,
} from './patterns.ts';
import { mountChordLibrary, type ChordLibrary } from './playground-chords.ts';
import { createPlaygroundMarkup } from './playground-markup.ts';

/**
 * `OpenLyricPlayerPlayground` — hear an Open Lyric song's strumming patterns,
 * and every chord Open Lyric offers, on guitars, keyboards, ukuleles and
 * basses. Patterns are written in the notation's `Strumming Patterns`
 * syntax; it opens on the two patterns of the "Extended Worship Build" example
 * (Key E, 4/4, 70 bpm). Below them, every chord gets a card with its voicing
 * and a play button (`playground-chords.ts`).
 *
 * The UI over an {@link OpenLyricPlayer}. It renders into a root element of
 * its own inside `container`, and its styles are scoped to that root.
 *
 * Settings and patterns persist in localStorage under `storageKey` — a
 * convenience only; it starts from the example whenever nothing usable is
 * stored.
 */

export type OpenLyricPlayerTheme = 'light' | 'dark';

export interface OpenLyricPlayerPlaygroundOptions {
  /** Where the playground renders. Its existing content is left alone. */
  container: HTMLElement;
  /** A player to share with the host; otherwise the playground makes one. */
  player?: OpenLyricPlayer;
  /** `light` or `dark`; omitted, the system's colour scheme decides. */
  theme?: OpenLyricPlayerTheme;
  /**
   * localStorage key for the settings and patterns. Default
   * `openLyricStrumPlayer.v2`; `null` keeps nothing between visits.
   */
  storageKey?: string | null;
}

interface PlaySettings {
  key: string;
  time: string;
  tempo: number;
  instrument: StrumInstrumentId;
  patterns: StrumPatternDefinition[];
}

type Refs = {
  key: HTMLSelectElement;
  time: HTMLSelectElement;
  tempo: HTMLInputElement;
  tempoRange: HTMLInputElement;
  instruments: HTMLElement;
  voicing: HTMLElement;
  patterns: HTMLElement;
  patternsEmpty: HTMLElement;
  restore: HTMLButtonElement;
  input: HTMLTextAreaElement;
  add: HTMLButtonElement;
  addError: HTMLElement;
  status: HTMLElement;
  chords: HTMLElement;
  chordsSummary: HTMLElement;
};

const REF_NAMES: readonly (keyof Refs)[] = [
  'key',
  'time',
  'tempo',
  'tempoRange',
  'instruments',
  'voicing',
  'patterns',
  'patternsEmpty',
  'restore',
  'input',
  'add',
  'addError',
  'status',
  'chords',
  'chordsSummary',
];

const DEFAULT_STORAGE_KEY = 'openLyricStrumPlayer.v2';
const TEMPO_MIN = 20;
const TEMPO_MAX = 300;
const KEYS: readonly string[] = CONFIG_KEY_VALUES;
const TIME_SIGNATURES: readonly string[] = CONFIG_ENUM_FIELD_VALUES.Time;
const THEMES: readonly OpenLyricPlayerTheme[] = ['light', 'dark'];

/** The `Strumming Patterns` of `examples/example1.md`. */
const EXAMPLE_PATTERNS: readonly StrumPatternDefinition[] = [
  { id: 'example-1', label: 'Slow rolling pulse', source: 'd--u-- | d-u-d-' },
  { id: 'example-2', label: 'Lift on the chorus', source: 'ddu--u | d-d-du' },
];

const DEFAULT_SETTINGS: Omit<PlaySettings, 'patterns'> = {
  key: 'E',
  time: '4/4',
  tempo: 70,
  instrument: 'guitar',
};

const ARROW_SVG =
  '<svg viewBox="0 0 14 28" aria-hidden="true"><path d="M7 3v21M2.5 19.5 7 24.5l4.5-5"/></svg>';

let instanceCount = 0;

// ——— The stylesheet: one <style> per page, however many playgrounds ———
//
// Inline (`?inline`), not a <link> to the emitted .css: a Vite dev host serves
// a `.css` under `node_modules` as a JavaScript HMR module, and a browser
// refuses a stylesheet that is not `text/css`. See `OpenLyricPluginPlayer.ts`.

let stylesheetUsers = 0;
let stylesheet: HTMLStyleElement | null = null;

function acquireStylesheet() {
  stylesheetUsers += 1;

  if (!stylesheet) {
    stylesheet = document.createElement('style');
    stylesheet.textContent = playgroundCss;
    stylesheet.dataset.olpStylesheet = '';
    document.head.append(stylesheet);
  }
}

function releaseStylesheet() {
  stylesheetUsers = Math.max(0, stylesheetUsers - 1);

  if (!stylesheetUsers) {
    stylesheet?.remove();
    stylesheet = null;
  }
}

// ——— Settings ———

function copyExamplePatterns(): StrumPatternDefinition[] {
  return EXAMPLE_PATTERNS.map((definition) => ({ ...definition }));
}

function clampTempo(value: unknown): number | null {
  const tempo = Math.round(Number(value));

  return Number.isFinite(tempo)
    ? Math.min(TEMPO_MAX, Math.max(TEMPO_MIN, tempo))
    : null;
}

function isUsableDefinition(value: any): value is StrumPatternDefinition {
  if (
    !value ||
    typeof value.id !== 'string' ||
    typeof value.label !== 'string' ||
    typeof value.source !== 'string'
  ) {
    return false;
  }

  try {
    parseOpenLyricPattern(value, '4/4');
    return true;
  } catch {
    return false;
  }
}

function readSettings(storageKey: string | null): PlaySettings {
  let stored: any = null;

  try {
    stored = storageKey
      ? JSON.parse(localStorage.getItem(storageKey) ?? 'null')
      : null;
  } catch {
    stored = null;
  }

  if (!stored || typeof stored !== 'object') {
    return { ...DEFAULT_SETTINGS, patterns: copyExamplePatterns() };
  }

  const storedPatterns = Array.isArray(stored.patterns)
    ? stored.patterns
        .filter(isUsableDefinition)
        .map(({ id, label, source }: StrumPatternDefinition) => ({
          id,
          label,
          source,
        }))
    : null;

  return {
    key: KEYS.includes(stored.key) ? stored.key : DEFAULT_SETTINGS.key,
    time: TIME_SIGNATURES.includes(stored.time)
      ? stored.time
      : DEFAULT_SETTINGS.time,
    tempo: clampTempo(stored.tempo) ?? DEFAULT_SETTINGS.tempo,
    instrument:
      getStrumInstrument(stored.instrument)?.id ?? DEFAULT_SETTINGS.instrument,
    patterns: storedPatterns ?? copyExamplePatterns(),
  };
}

function describeStep(step: StrumStep | null): string {
  return step ? step.direction : 'rest';
}

function createPlayIcon(): SVGSVGElement[] {
  const template = document.createElement('template');

  template.innerHTML =
    '<svg class="icon-play" viewBox="0 0 24 24" aria-hidden="true"><path d="M8.5 5.8v12.4a.8.8 0 0 0 1.2.7l9.6-6.2a.8.8 0 0 0 0-1.4L9.7 5.1a.8.8 0 0 0-1.2.7z"/></svg>' +
    '<svg class="icon-stop" viewBox="0 0 24 24" aria-hidden="true"><rect x="6.5" y="6.5" width="11" height="11" rx="1.6"/></svg>';

  return Array.from(template.content.children) as SVGSVGElement[];
}

function fillStep(element: HTMLElement, pattern: StrumPattern, index: number) {
  const step = pattern.steps[index];
  const count = pattern.counts[index] ?? String(index + 1);
  const description = `${count} (step ${index + 1}): ${describeStep(step)}`;
  const [stroke, countElement] = Array.from(element.children) as HTMLElement[];

  element.classList.toggle('is-active', Boolean(step));
  element.classList.toggle('step--break', pattern.groupBreaks.includes(index));
  element.setAttribute('aria-label', `${description}. Press to change.`);
  element.title = description;
  stroke.innerHTML = step ? ARROW_SVG : '';
  stroke.firstElementChild?.classList.toggle(
    'stroke-up',
    step?.direction === 'up',
  );
  countElement.textContent = count;
}

function createStep(pattern: StrumPattern, index: number): HTMLElement {
  const element = document.createElement('button');

  element.type = 'button';
  element.className = 'step';
  element.dataset.step = String(index + 1);
  element.dataset.action = 'cycle';

  for (const part of ['stroke', 'count']) {
    const child = document.createElement('span');

    child.className = `step__${part}`;
    child.setAttribute('aria-hidden', 'true');
    element.append(child);
  }

  fillStep(element, pattern, index);
  return element;
}

function createPatternCard(pattern: StrumPattern): HTMLElement {
  const card = document.createElement('article');
  const header = document.createElement('div');
  const play = document.createElement('button');
  const spinner = document.createElement('span');
  const name = document.createElement('h3');
  const remove = document.createElement('button');
  const steps = document.createElement('div');
  const source = document.createElement('p');

  card.className = 'pattern-card';
  card.dataset.patternId = pattern.id;
  card.dataset.state = 'idle';
  header.className = 'pattern-card__header';
  play.className = 'pattern-card__play';
  play.type = 'button';
  play.dataset.action = 'toggle';
  spinner.className = 'spinner';
  spinner.setAttribute('aria-hidden', 'true');
  play.append(...createPlayIcon(), spinner);
  name.className = 'pattern-card__name';
  name.textContent = pattern.label;
  remove.className = 'pattern-card__remove';
  remove.type = 'button';
  remove.dataset.action = 'remove';
  remove.textContent = '×';
  remove.title = `Remove ${pattern.label}`;
  remove.setAttribute('aria-label', `Remove ${pattern.label}`);
  header.append(play, name, remove);

  steps.className = 'pattern-card__steps';
  steps.setAttribute('role', 'group');
  steps.setAttribute('aria-label', `${pattern.label} steps`);
  steps.append(...pattern.steps.map((_, index) => createStep(pattern, index)));

  source.className = 'pattern-card__source';
  source.append(
    Object.assign(document.createElement('code'), {
      textContent: pattern.source,
    }),
  );
  card.append(header, steps, source);

  return card;
}

export class OpenLyricPlayerPlayground {
  /** The player behind the UI — the one passed in, or the playground's own. */
  readonly player: OpenLyricPlayer;

  #container: HTMLElement;
  #ownsPlayer: boolean;
  #storageKey: string | null;
  #theme: OpenLyricPlayerTheme | undefined;
  #prefix: string;
  #root: HTMLElement | null = null;
  #refs: Refs | null = null;
  #abort: AbortController | null = null;
  #unsubscribe: (() => void)[] = [];
  #settings: PlaySettings;
  #patterns = new Map<string, StrumPattern>();
  #currentStep: HTMLElement | null = null;
  #chordLibrary: ChordLibrary | null = null;
  #idCounter = 0;

  constructor(options: OpenLyricPlayerPlaygroundOptions) {
    if (!(options?.container instanceof HTMLElement)) {
      throw new TypeError(
        'OpenLyricPlayerPlayground needs a `container` element.',
      );
    }

    this.#container = options.container;
    this.#ownsPlayer = !options.player;
    this.player = options.player ?? new OpenLyricPlayer();
    this.#storageKey =
      options.storageKey === undefined
        ? DEFAULT_STORAGE_KEY
        : options.storageKey;
    this.#theme = this.#checkTheme(options.theme);
    this.#prefix = `olp-${++instanceCount}`;
    this.#settings = readSettings(this.#storageKey);
  }

  /** The root element, once rendered. */
  get element(): HTMLElement | null {
    return this.#root;
  }

  /** `light`, `dark`, or `undefined` when the system decides. */
  get theme(): OpenLyricPlayerTheme | undefined {
    return this.#theme;
  }

  /** Switches the theme; `undefined` hands it back to the system. */
  setTheme(theme: OpenLyricPlayerTheme | undefined): void {
    this.#theme = this.#checkTheme(theme);
    this.#applyTheme();
  }

  /**
   * Renders into the container. Calling it again renders afresh, keeping the
   * settings and patterns.
   */
  render(): this {
    this.#teardown();
    acquireStylesheet();

    const root = document.createElement('div');
    const abort = new AbortController();

    root.className = 'olp-playground';
    root.innerHTML = createPlaygroundMarkup(this.#prefix);
    this.#root = root;
    this.#abort = abort;
    this.#refs = Object.fromEntries(
      REF_NAMES.map((name) => {
        const element = root.querySelector(`[data-olp-ref="${name}"]`);

        if (!element) {
          throw new Error(`The playground markup is missing ${name}.`);
        }

        return [name, element];
      }),
    ) as Refs;
    this.#applyTheme();
    this.#container.append(root);

    this.#wire(abort.signal);
    this.#renderSongControls();
    this.#renderInstruments();
    this.#renderVoicing();
    this.#renderPatterns();
    this.#loadChords(abort.signal);

    return this;
  }

  /**
   * Removes the playground and stops its pattern. A player the playground
   * made is destroyed with it; one passed in is left to its owner.
   */
  destroy(): void {
    this.#teardown();

    if (this.#ownsPlayer) {
      this.player.destroy();
    }
  }

  #teardown() {
    if (!this.#root) {
      return;
    }

    if (this.#patterns.has(this.player.patternId ?? '')) {
      this.player.stop();
    }

    this.#abort?.abort();
    this.#unsubscribe.forEach((unsubscribe) => unsubscribe());
    this.#unsubscribe = [];
    this.#root.remove();
    this.#root = null;
    this.#refs = null;
    this.#abort = null;
    this.#chordLibrary = null;
    this.#currentStep = null;
    releaseStylesheet();
  }

  #checkTheme(theme: unknown): OpenLyricPlayerTheme | undefined {
    if (theme === undefined || theme === null) {
      return undefined;
    }

    if (!THEMES.includes(theme as OpenLyricPlayerTheme)) {
      throw new TypeError(
        `Unknown theme “${String(theme)}” — use 'light' or 'dark'.`,
      );
    }

    return theme as OpenLyricPlayerTheme;
  }

  #applyTheme() {
    if (!this.#root) {
      return;
    }

    if (this.#theme) {
      this.#root.dataset.theme = this.#theme;
    } else {
      delete this.#root.dataset.theme;
    }

    // SVGuitar reads the diagram inks once, as it draws.
    this.#chordLibrary?.refresh();
  }

  #saveSettings() {
    if (!this.#storageKey) {
      return;
    }

    try {
      localStorage.setItem(this.#storageKey, JSON.stringify(this.#settings));
    } catch {
      // Storage is a convenience; the playground works without it.
    }
  }

  #getInstrument(): StrumInstrument {
    return (
      getStrumInstrument(this.#settings.instrument) ?? STRUM_INSTRUMENTS[0]
    );
  }

  #getVoicing(): StrumVoicing | null {
    return this.player.getVoicing(
      this.#settings.instrument,
      this.#settings.key,
    );
  }

  #setStatus(message: string, tone: 'info' | 'error' = 'info') {
    if (this.#refs) {
      this.#refs.status.textContent = message;
      this.#refs.status.dataset.tone = tone;
    }
  }

  #loadChords(signal: AbortSignal) {
    this.player.loadChords().then(
      () => {
        if (signal.aborted || !this.#root || !this.#refs) {
          return;
        }

        this.#renderVoicing();
        this.#chordLibrary = mountChordLibrary({
          root: this.#root,
          groups: this.#refs.chords,
          summary: this.#refs.chordsSummary,
          cardId: `${this.#prefix}-chord-card`,
          player: this.player,
          signal,
          getInstrument: () => this.#getInstrument(),
          getKey: () => this.#settings.key,
          onError: (message) => this.#setStatus(message, 'error'),
        });
      },
      (error) => {
        if (signal.aborted || !this.#refs) {
          return;
        }

        this.#refs.voicing.textContent = '';
        this.#setStatus(
          `Could not load chord voicings: ${error instanceof Error ? error.message : String(error)}`,
          'error',
        );
      },
    );
  }

  // ——— Song controls ———

  #renderSongControls() {
    const refs = this.#refs!;
    const settings = this.#settings;

    refs.key.replaceChildren(
      ...KEYS.map((key) => new Option(key, key, false, key === settings.key)),
    );
    refs.time.replaceChildren(
      ...TIME_SIGNATURES.map(
        (time) => new Option(time, time, false, time === settings.time),
      ),
    );
    refs.tempo.value = String(settings.tempo);
    refs.tempoRange.value = String(settings.tempo);
  }

  #setTempo(value: unknown) {
    const refs = this.#refs!;
    const tempo = clampTempo(value) ?? this.#settings.tempo;

    this.#settings.tempo = tempo;
    refs.tempo.value = String(tempo);
    refs.tempoRange.value = String(tempo);
  }

  // ——— Instruments ———

  #renderInstruments() {
    this.#refs!.instruments.replaceChildren(
      ...STRUM_INSTRUMENTS.map((instrument) => {
        const label = document.createElement('label');
        const input = document.createElement('input');
        const text = document.createElement('span');
        const name = document.createElement('span');
        const sound = document.createElement('span');
        const toggle = document.createElement('span');

        label.className = 'instrument';
        input.type = 'radio';
        input.name = `${this.#prefix}-instrument`;
        input.value = instrument.id;
        input.checked = instrument.id === this.#settings.instrument;
        text.className = 'instrument__text';
        name.className = 'instrument__name';
        name.textContent = instrument.label;
        sound.className = 'instrument__sound';
        sound.textContent = instrument.soundfont.title;
        toggle.className = 'instrument__switch';
        toggle.setAttribute('aria-hidden', 'true');
        text.append(name, sound);
        label.append(input, text, toggle);
        return label;
      }),
    );
  }

  #renderVoicing() {
    const refs = this.#refs!;

    if (!this.player.chordsLoaded) {
      refs.voicing.textContent = 'Loading chord voicings…';
      return;
    }

    const voicing = this.#getVoicing();
    const instrument = this.#getInstrument();

    if (!voicing) {
      refs.voicing.textContent = `No ${instrument.label} voicing for the key of ${this.#settings.key}.`;
      return;
    }

    const summary = document.createElement('div');
    const notes = document.createElement('div');

    summary.append('Strums ');
    summary.append(
      Object.assign(document.createElement('strong'), {
        textContent: voicing.chord,
      }),
    );

    if (voicing.card.kind === 'diagram') {
      const { frets, baseFret } = voicing.card.voicing;

      summary.append(' — frets ');
      summary.append(
        Object.assign(document.createElement('code'), {
          textContent: frets
            .map((fret) =>
              fret < 0 ? 'x' : String(fret === 0 ? 0 : fret + baseFret - 1),
            )
            .join(' '),
        }),
      );
    }

    notes.className = 'voicing__notes';
    notes.append(
      ...voicing.midi.map((midi) =>
        Object.assign(document.createElement('span'), {
          className: 'voicing__note',
          textContent: getMidiNoteName(midi, this.#settings.key),
        }),
      ),
    );
    refs.voicing.replaceChildren(summary, notes);
  }

  // ——— Patterns ———

  #findCard(patternId: string): HTMLElement | null {
    return (
      this.#refs?.patterns.querySelector<HTMLElement>(
        `.pattern-card[data-pattern-id="${CSS.escape(patternId)}"]`,
      ) ?? null
    );
  }

  #renderPatterns() {
    const refs = this.#refs!;

    this.#patterns = new Map();

    for (const definition of this.#settings.patterns) {
      try {
        this.#patterns.set(
          definition.id,
          parseOpenLyricPattern(definition, this.#settings.time),
        );
      } catch (error) {
        console.warn(`Skipping pattern ${definition.label}:`, error);
      }
    }

    this.#currentStep = null;
    refs.patterns.replaceChildren(
      ...Array.from(this.#patterns.values(), createPatternCard),
    );
    refs.patternsEmpty.hidden = this.#patterns.size > 0;
    this.#syncPlaybackState();
  }

  #syncPlaybackState() {
    const refs = this.#refs;

    if (!refs) {
      return;
    }

    for (const card of refs.patterns.querySelectorAll<HTMLElement>(
      '.pattern-card',
    )) {
      const isActive = card.dataset.patternId === this.player.patternId;
      const state = isActive ? this.player.state : 'idle';
      const play = card.querySelector<HTMLButtonElement>(
        '.pattern-card__play',
      )!;
      const label =
        this.#patterns.get(card.dataset.patternId!)?.label ?? 'pattern';

      card.dataset.state = state;
      play.setAttribute('aria-pressed', String(state !== 'idle'));
      play.setAttribute(
        'aria-label',
        state === 'idle' ? `Play ${label}` : `Stop ${label}`,
      );
      play.title = state === 'idle' ? `Play ${label}` : `Stop ${label}`;
    }
  }

  #showCurrentStep(patternId: string, stepNumber: number | null) {
    this.#currentStep?.classList.remove('is-current');
    this.#currentStep =
      stepNumber == null
        ? null
        : (this.#findCard(patternId)?.querySelector<HTMLElement>(
            `.step[data-step="${stepNumber}"]`,
          ) ?? null);
    this.#currentStep?.classList.add('is-current');
  }

  #startPattern(patternId: string) {
    const pattern = this.#patterns.get(patternId);

    if (!pattern) {
      return;
    }

    if (!this.#getVoicing()) {
      this.#setStatus(
        this.player.chordsLoaded
          ? `No ${this.#getInstrument().label} voicing for the key of ${this.#settings.key}.`
          : 'Chord voicings are still loading.',
        'error',
      );
      return;
    }

    this.player
      .playPattern({
        pattern,
        key: this.#settings.key,
        tempo: this.#settings.tempo,
        time: this.#settings.time,
        instrument: this.#settings.instrument,
      })
      .catch((error) =>
        this.#setStatus(
          `Could not play: ${error instanceof Error ? error.message : String(error)}`,
          'error',
        ),
      );
  }

  /** Picks up a changed key, time, tempo or instrument without a new press. */
  #restartIfPlaying() {
    const { patternId } = this.player;

    if (
      this.player.state !== 'idle' &&
      patternId &&
      this.#patterns.has(patternId)
    ) {
      this.#startPattern(patternId);
    }
  }

  #cycleStep(patternId: string, index: number) {
    const settings = this.#settings;
    const position = settings.patterns.findIndex(
      (definition) => definition.id === patternId,
    );

    if (position === -1) {
      return;
    }

    const definition = cycleStrumPatternStep(
      settings.patterns[position],
      index,
      settings.time,
    );
    const pattern = parseOpenLyricPattern(definition, settings.time);
    const card = this.#findCard(patternId);

    settings.patterns[position] = definition;
    this.#patterns.set(patternId, pattern);
    this.#saveSettings();

    // Refill in place, so the pressed step keeps focus.
    card
      ?.querySelectorAll<HTMLElement>('.step')
      .forEach((element, stepIndex) => fillStep(element, pattern, stepIndex));

    const source = card?.querySelector('.pattern-card__source code');

    if (source) {
      source.textContent = pattern.source;
    }

    this.player.updatePattern(pattern);
  }

  #removePattern(patternId: string) {
    const pattern = this.#patterns.get(patternId);

    if (this.player.patternId === patternId) {
      this.player.stop();
    }

    this.#settings.patterns = this.#settings.patterns.filter(
      (definition) => definition.id !== patternId,
    );
    this.#saveSettings();
    this.#renderPatterns();
    this.#setStatus(pattern ? `Removed ${pattern.label}.` : '');
  }

  #createPatternId() {
    this.#idCounter += 1;
    return `custom-${Date.now().toString(36)}-${this.#idCounter}`;
  }

  #createLabeler() {
    let next =
      this.#settings.patterns.reduce((highest, definition) => {
        const match = /^Pattern (\d+)$/.exec(definition.label);

        return match ? Math.max(highest, Number(match[1])) : highest;
      }, 0) + 1;

    return () => `Pattern ${next++}`;
  }

  #addPatterns() {
    const refs = this.#refs!;

    refs.addError.textContent = '';

    try {
      const added = readStrumPatternInput(
        refs.input.value,
        () => this.#createPatternId(),
        this.#createLabeler(),
      );

      this.#settings.patterns.push(...added);
      this.#saveSettings();
      this.#renderPatterns();
      refs.input.value = '';
      this.#setStatus(
        `Added ${added.map((definition) => definition.label).join(', ')}.`,
      );
    } catch (error) {
      refs.addError.textContent =
        error instanceof Error ? error.message : String(error);
    }
  }

  #restoreExamplePatterns() {
    const others = this.#settings.patterns.filter(
      (definition) =>
        !EXAMPLE_PATTERNS.some((example) => example.id === definition.id),
    );

    if (
      EXAMPLE_PATTERNS.some((example) => example.id === this.player.patternId)
    ) {
      this.player.stop();
    }

    this.#settings.patterns = [...copyExamplePatterns(), ...others];
    this.#saveSettings();
    this.#renderPatterns();
    this.#setStatus('Restored the example patterns.');
  }

  // ——— Wiring ———

  #onPlayerState({ state, patternId, error }: OpenLyricPlayerStateEvent) {
    this.#syncPlaybackState();

    if (state !== 'playing') {
      this.#showCurrentStep('', null);
    }

    const pattern = patternId ? this.#patterns.get(patternId) : null;

    // A pattern the host started on a shared player is not ours to report.
    if (patternId && !pattern) {
      return;
    }

    if (state === 'loading') {
      this.#setStatus(`Loading ${this.#getInstrument().soundfont.title}…`);
    } else if (state === 'playing' && pattern) {
      this.#setStatus(
        `Playing ${pattern.label} — ${this.#getVoicing()?.chord ?? this.#settings.key} on ${this.#getInstrument().label}, ${this.#settings.tempo} bpm, ${this.#settings.time}.`,
      );
    } else if (error) {
      this.#setStatus(
        `Could not play: ${error instanceof Error ? error.message : String(error)}`,
        'error',
      );
    } else {
      this.#setStatus('');
    }
  }

  #wire(signal: AbortSignal) {
    const refs = this.#refs!;
    const settings = this.#settings;
    const listen = { signal };

    this.#unsubscribe.push(
      this.player.on('state', (event) => this.#onPlayerState(event)),
      this.player.on('step', ({ patternId, stepNumber }) =>
        this.#showCurrentStep(patternId, stepNumber),
      ),
    );

    refs.patterns.addEventListener(
      'click',
      (event) => {
        const target = (event.target as Element).closest<HTMLElement>(
          '[data-action]',
        );
        const patternId =
          target?.closest<HTMLElement>('.pattern-card')?.dataset.patternId;

        if (!target || !patternId) {
          return;
        }

        switch (target.dataset.action) {
          case 'toggle':
            if (
              this.player.patternId === patternId &&
              this.player.state !== 'idle'
            ) {
              this.player.stop();
            } else {
              this.#startPattern(patternId);
            }
            break;
          case 'remove':
            this.#removePattern(patternId);
            break;
          case 'cycle':
            this.#cycleStep(patternId, Number(target.dataset.step) - 1);
            break;
        }
      },
      listen,
    );

    refs.key.addEventListener(
      'change',
      () => {
        settings.key = refs.key.value;
        this.#saveSettings();
        this.#renderVoicing();
        // Note names are spelled the way the song's key spells them.
        this.#chordLibrary?.refresh();
        this.#restartIfPlaying();
      },
      listen,
    );

    refs.time.addEventListener(
      'change',
      () => {
        settings.time = refs.time.value;
        this.#saveSettings();
        this.#renderPatterns();
        this.#restartIfPlaying();
      },
      listen,
    );

    refs.tempoRange.addEventListener(
      'input',
      () => this.#setTempo(refs.tempoRange.value),
      listen,
    );

    for (const input of [refs.tempo, refs.tempoRange]) {
      input.addEventListener(
        'change',
        () => {
          this.#setTempo(input.value);
          this.#saveSettings();
          this.#restartIfPlaying();
        },
        listen,
      );
    }

    refs.instruments.addEventListener(
      'change',
      (event) => {
        const instrument = getStrumInstrument(
          (event.target as HTMLInputElement).value,
        );

        if (!instrument) {
          return;
        }

        settings.instrument = instrument.id;
        this.#saveSettings();
        this.#renderVoicing();
        this.#chordLibrary?.refresh();

        if (this.player.state !== 'idle') {
          this.#restartIfPlaying();
        } else {
          // Warm the soundfont up while the choice is fresh (this is a gesture).
          this.player.preload(instrument.id).catch(() => {});
        }
      },
      listen,
    );

    refs.add.addEventListener('click', () => this.#addPatterns(), listen);
    refs.input.addEventListener(
      'keydown',
      (event) => {
        if (event.key === 'Enter' && (event.ctrlKey || event.metaKey)) {
          event.preventDefault();
          this.#addPatterns();
        }
      },
      listen,
    );
    refs.restore.addEventListener(
      'click',
      () => this.#restoreExamplePatterns(),
      listen,
    );
  }
}
