import { getStrumSound, type StrumSound } from './instrument-sounds.ts';
import {
  getStrumInstrument,
  type StrumInstrument,
  type StrumInstrumentId,
  type StrumSoundfont,
} from './instruments.ts';
import { getStrumStepSeconds, type StrumPattern } from './patterns.ts';
import {
  planChordRoll,
  planStroke,
  type PlannedNote,
  type StrokePlan,
} from './strum-plan.ts';
import {
  WebAudioStrumSoundEngine,
  type StrumSoundEngine,
  type StrumVoice,
} from './StrumSoundEngine.ts';
import {
  loadSoundfontPreset,
  loadWebAudioFontPlayer,
  type WebAudioFontPlayerConstructor,
  type WebAudioFontPlayerInstance,
  type WebAudioFontPreset,
} from './webaudiofont.ts';

/**
 * Plays one strum pattern at a time, looping, on the audio clock: step 1
 * sounds {@link START_DELAY_SECONDS} after the press, each later step one
 * step-length after the one before (`getStrumStepSeconds`), and after the last
 * step the grid starts again. A short timer queues strokes up to
 * {@link SCHEDULE_AHEAD_SECONDS} ahead. Each stroke is played the way its
 * instrument is (`planStroke`) and sounded by the voice engine
 * (`StrumSoundEngine.ts`), where every string rings until it is struck again.
 *
 * A stop cancels the queued strokes that have not sounded yet, lets a stroke
 * under way finish, and then damps the strings still ringing, as a player's
 * palm does (the instrument's `release`).
 *
 * It also plays a chord card's roll (`planChordRoll`), alongside a pattern and
 * untouched by a stop. A new roll damps the one before it.
 */

export interface StrumPlaybackRequest {
  pattern: StrumPattern;
  tempo: number;
  timeSignature: string;
  /** MIDI notes the pattern strums, in string order (piano: low to high). */
  chord: readonly number[];
  instrument: StrumInstrumentId;
}

export interface StrumChordRequest {
  /** The chord's notes, in the order they are struck. */
  midi: readonly number[];
  instrument: StrumInstrumentId;
}

export type StrumPlayerState = 'idle' | 'loading' | 'playing';

/** Browser seams, swapped out by the unit tests. */
export interface StrumPlayerRuntime {
  createAudioContext(): AudioContext;
  loadPlayer(): Promise<WebAudioFontPlayerConstructor>;
  loadPreset(
    player: WebAudioFontPlayerInstance,
    context: BaseAudioContext,
    soundfont: StrumSoundfont,
  ): Promise<WebAudioFontPreset>;
  /** The voice engine that sounds the notes, on the player's context. */
  createEngine(context: AudioContext): StrumSoundEngine;
  /** Draws a player's human wander, `0 ≤ n < 1`. Default `Math.random`. */
  random?(): number;
}

export const browserStrumPlayerRuntime: StrumPlayerRuntime = {
  createAudioContext() {
    const AudioContextConstructor =
      globalThis.AudioContext ?? (globalThis as any).webkitAudioContext;

    return new AudioContextConstructor();
  },
  loadPlayer: loadWebAudioFontPlayer,
  loadPreset: loadSoundfontPreset,
  createEngine: (context) => new WebAudioStrumSoundEngine(context),
};

const SCHEDULER_INTERVAL_MS = 25;
export const SCHEDULE_AHEAD_SECONDS = 0.1;
/** Head room between the press and the first stroke. */
export const START_DELAY_SECONDS = 0.05;
/** Two times this close are the same instant. */
const TIME_EPSILON = 1e-6;
/** The engine groups a pattern's notes, and a chord card's, apart. */
export const PATTERN_GROUP = 'pattern';
export const CHORD_GROUP = 'chord';

interface Playback {
  context: AudioContext;
  engine: StrumSoundEngine;
  preset: WebAudioFontPreset;
  instrument: StrumInstrumentId;
  sound: StrumSound;
  pattern: StrumPattern;
  chord: readonly number[];
  stepSeconds: number;
  startTime: number;
  /** How many step-lengths after the start the next step sounds. */
  nextTick: number;
  /** The 0-based step of the pattern that tick plays. */
  nextStep: number;
}

/** The notes one stroke scheduled — cancelled if a stop beats it. */
interface StrokeRecord {
  /** When its first note sounds. */
  time: number;
  /** When its last note sounds. */
  end: number;
  voices: StrumVoice[];
}

export class StrumPlayer {
  onStep: ((patternId: string, stepNumber: number) => void) | null = null;
  onStateChange:
    | ((
        state: StrumPlayerState,
        patternId: string | null,
        error?: unknown,
      ) => void)
    | null = null;

  #runtime: StrumPlayerRuntime;
  #context: AudioContext | null = null;
  #engine: StrumSoundEngine | null = null;
  #playerLoad: Promise<WebAudioFontPlayerInstance> | null = null;
  #presetLoads = new Map<string, Promise<WebAudioFontPreset>>();
  #playback: Playback | null = null;
  #state: StrumPlayerState = 'idle';
  #statePatternId: string | null = null;
  #token = 0;
  #chordToken = 0;
  #records: StrokeRecord[] = [];
  #timer: ReturnType<typeof setInterval> | null = null;
  #uiTimers = new Set<ReturnType<typeof setTimeout>>();

  constructor(runtime: StrumPlayerRuntime = browserStrumPlayerRuntime) {
    this.#runtime = runtime;
  }

  get state(): StrumPlayerState {
    return this.#state;
  }

  /** The pattern loading or playing, if any. */
  get patternId(): string | null {
    return this.#statePatternId;
  }

  /**
   * Creates and resumes the audio context without playing anything. Browsers
   * only allow that from a user gesture, before its first `await` — so a
   * caller with its own async work to do before {@link play} calls this first.
   */
  unlock(): void {
    void this.#ensureContext().resume?.();
  }

  /**
   * Loads and decodes a soundfont ahead of a play. Creates the audio context,
   * so call it from a user gesture.
   */
  async preload(soundfont: StrumSoundfont): Promise<void> {
    const context = this.#ensureContext();
    const player = await this.#ensurePlayer();

    await this.#ensurePreset(player, context, soundfont);
  }

  /**
   * Stops whatever plays and starts `request`. Call it straight from the
   * user's gesture: the audio context is created and resumed before the first
   * `await`, as browsers require. Failures are reported through
   * `onStateChange`, not thrown.
   */
  async play(request: StrumPlaybackRequest): Promise<void> {
    this.stop();

    const token = ++this.#token;
    const context = this.#ensureContext();

    void context.resume?.();
    this.#setState('loading', request.pattern.id);

    try {
      const { soundfont } = getInstrument(request.instrument);
      const player = await this.#ensurePlayer();
      const preset = await this.#ensurePreset(player, context, soundfont);

      if (token === this.#token) {
        this.#start(request, context, preset);
      }
    } catch (error) {
      if (token === this.#token) {
        this.#setState('idle', null, error);
      }
    }
  }

  /**
   * Plays a chord card's roll (`planChordRoll`). It sounds alongside a playing
   * pattern, and a stop leaves it ringing; the next roll damps it. Call it
   * from the user's gesture, like {@link play}.
   *
   * Of presses made while the soundfont loads, only the last one plays.
   * Resolves `true` once the notes are queued, `false` when a later press took
   * over; rejects when the player or soundfont fails to load.
   */
  async playChord(request: StrumChordRequest): Promise<boolean> {
    const token = ++this.#chordToken;
    const context = this.#ensureContext();

    void context.resume?.();

    const { soundfont } = getInstrument(request.instrument);
    const player = await this.#ensurePlayer();
    const preset = await this.#ensurePreset(player, context, soundfont);

    if (token !== this.#chordToken) {
      return false;
    }

    const engine = this.#ensureEngine(context);
    const sound = getStrumSound(request.instrument);
    const start = context.currentTime + START_DELAY_SECONDS;

    // The hand leaves the last roll's strings as it starts this one.
    engine.damp(CHORD_GROUP, start, sound.release);

    for (const note of planChordRoll(request.midi, sound, this.#random)) {
      this.#sound(engine, preset, sound, note, start, {
        slot: `${CHORD_GROUP}:${request.instrument}:${note.slot}`,
        group: CHORD_GROUP,
      });
    }

    return true;
  }

  /** Swaps in an edited pattern mid-run; its next step plays the edit. */
  updatePattern(pattern: StrumPattern) {
    const playback = this.#playback;

    if (!playback || playback.pattern.id !== pattern.id) {
      return;
    }

    playback.pattern = pattern;

    if (playback.nextStep >= pattern.steps.length) {
      playback.nextStep = 0;
    }
  }

  stop() {
    this.#token += 1;

    const wasActive = this.#state !== 'idle';
    const playback = this.#playback;
    const now = this.#context?.currentTime ?? 0;
    let settle = now;

    this.#playback = null;
    this.#clearUiTimers();
    this.#stopTimer();

    for (const record of this.#records) {
      if (record.time > now + TIME_EPSILON) {
        record.voices.forEach((voice) => voice.cancel());
      } else {
        settle = Math.max(settle, record.end);
      }
    }

    this.#records = [];

    if (playback) {
      playback.engine.damp(PATTERN_GROUP, settle, playback.sound.release);
    }

    if (wasActive) {
      this.#setState('idle', null);
    }
  }

  #random = () => (this.#runtime.random ?? Math.random)();

  #ensureContext(): AudioContext {
    this.#context ??= this.#runtime.createAudioContext();
    return this.#context;
  }

  #ensureEngine(context: AudioContext): StrumSoundEngine {
    this.#engine ??= this.#runtime.createEngine(context);
    return this.#engine;
  }

  #ensurePlayer(): Promise<WebAudioFontPlayerInstance> {
    if (!this.#playerLoad) {
      const load = this.#runtime.loadPlayer().then((Player) => new Player());

      this.#playerLoad = load;
      load.catch(() => {
        if (this.#playerLoad === load) {
          this.#playerLoad = null;
        }
      });
    }

    return this.#playerLoad;
  }

  #ensurePreset(
    player: WebAudioFontPlayerInstance,
    context: BaseAudioContext,
    soundfont: StrumSoundfont,
  ): Promise<WebAudioFontPreset> {
    let load = this.#presetLoads.get(soundfont.key);

    if (!load) {
      const pending = this.#runtime.loadPreset(player, context, soundfont);

      load = pending;
      this.#presetLoads.set(soundfont.key, pending);
      pending.catch(() => {
        if (this.#presetLoads.get(soundfont.key) === pending) {
          this.#presetLoads.delete(soundfont.key);
        }
      });
    }

    return load;
  }

  #start(
    request: StrumPlaybackRequest,
    context: AudioContext,
    preset: WebAudioFontPreset,
  ) {
    this.#playback = {
      context,
      engine: this.#ensureEngine(context),
      preset,
      instrument: request.instrument,
      sound: getStrumSound(request.instrument),
      pattern: request.pattern,
      chord: [...request.chord],
      stepSeconds: getStrumStepSeconds(request.tempo, request.timeSignature),
      startTime: context.currentTime + START_DELAY_SECONDS,
      nextTick: 0,
      nextStep: 0,
    };

    this.#setState('playing', request.pattern.id);
    this.#timer ??= setInterval(() => this.#tick(), SCHEDULER_INTERVAL_MS);
    this.#tick();
  }

  #tick() {
    const playback = this.#playback;

    if (!playback || !playback.pattern.steps.length) {
      return;
    }

    const now = playback.context.currentTime;
    const horizon = now + SCHEDULE_AHEAD_SECONDS;
    let time = playback.startTime + playback.nextTick * playback.stepSeconds;

    while (time < horizon) {
      this.#playStep(playback, playback.nextStep, time);
      playback.nextTick += 1;
      playback.nextStep =
        (playback.nextStep + 1) % playback.pattern.steps.length;
      time = playback.startTime + playback.nextTick * playback.stepSeconds;
    }

    this.#records = this.#records.filter((record) => record.end > now);
  }

  #playStep(playback: Playback, index: number, time: number) {
    this.#showStep(playback, index + 1, time);

    const plan = planStroke(
      playback.chord,
      playback.pattern.steps[index],
      playback.sound,
      this.#random,
    );

    if (plan) {
      this.#perform(playback, plan, time);
    }
  }

  #perform(playback: Playback, plan: StrokePlan, time: number) {
    const onset = time + plan.shift;
    const record: StrokeRecord = { time: onset, end: onset, voices: [] };

    for (const note of plan.notes) {
      const voice = this.#sound(
        playback.engine,
        playback.preset,
        playback.sound,
        note,
        onset,
        {
          slot: `${PATTERN_GROUP}:${playback.instrument}:${note.slot}`,
          group: PATTERN_GROUP,
        },
      );

      record.end = Math.max(record.end, onset + note.offset);

      if (voice) {
        record.voices.push(voice);
      }
    }

    this.#records.push(record);
  }

  #sound(
    engine: StrumSoundEngine,
    preset: WebAudioFontPreset,
    sound: StrumSound,
    note: PlannedNote,
    start: number,
    { slot, group }: { slot: string; group: string },
  ): StrumVoice | null {
    return engine.play({
      preset,
      sound,
      pitch: note.pitch,
      time: start + note.offset,
      velocity: note.velocity,
      detune: note.detune,
      pan: note.pan,
      slot,
      group,
    });
  }

  #showStep(playback: Playback, stepNumber: number, time: number) {
    const delay = Math.max(0, (time - playback.context.currentTime) * 1000);
    const timer = setTimeout(() => {
      this.#uiTimers.delete(timer);

      if (playback === this.#playback) {
        this.onStep?.(playback.pattern.id, stepNumber);
      }
    }, delay);

    this.#uiTimers.add(timer);
  }

  #clearUiTimers() {
    this.#uiTimers.forEach((timer) => clearTimeout(timer));
    this.#uiTimers.clear();
  }

  #stopTimer() {
    if (this.#timer != null) {
      clearInterval(this.#timer);
      this.#timer = null;
    }
  }

  #setState(
    state: StrumPlayerState,
    patternId: string | null,
    error?: unknown,
  ) {
    this.#state = state;
    this.#statePatternId = patternId;
    this.onStateChange?.(state, patternId, error);
  }
}

function getInstrument(id: StrumInstrumentId): StrumInstrument {
  const instrument = getStrumInstrument(id);

  if (!instrument) {
    throw new Error(`Unknown instrument “${id}”.`);
  }

  return instrument;
}
