import { SVGuitarChord } from 'svguitar';

import {
  getChordCardMidi,
  getOpenLyricChordGroups,
  type ChordCard,
} from './chord-library.ts';
import { createPianoBoard } from './chord-figure.ts';
import { getStrumSound } from './instrument-sounds.ts';
import { getMidiNoteName, type StrumInstrument } from './instruments.ts';
import { getChordRollSeconds } from './strum-plan.ts';
import type { OpenLyricPlayer } from './OpenLyricPlayer.ts';
import { START_DELAY_SECONDS } from './StrumPlayer.ts';

/**
 * The playground's Chords section: every chord Open Lyric offers. Point at a
 * chord (or focus it) and a card shows its voicing on the selected instrument
 * — a chord diagram, or piano keys — with a play button that rolls the chord.
 * Pressing the chord itself plays it too.
 *
 * The card stays up while the pointer is on it and goes shortly after the
 * pointer leaves.
 */

export interface ChordLibraryOptions {
  /** The playground root: the card mounts here, inside its theme tokens. */
  root: HTMLElement;
  groups: HTMLElement;
  summary: HTMLElement;
  /** Unique within the page — the card's id, for `aria-describedby`. */
  cardId: string;
  player: OpenLyricPlayer;
  /** Aborted when the playground goes; drops the document listeners. */
  signal: AbortSignal;
  getInstrument(): StrumInstrument;
  getKey(): string;
  onError(message: string): void;
}

export interface ChordLibrary {
  /** Re-reads the instrument and key into the chords and any open card. */
  refresh(): void;
}

const HIDE_DELAY_MS = 400;
const CARD_GAP_PX = 10;
const VIEWPORT_MARGIN_PX = 8;
/** How long a chord stays lit after its last note starts. */
const PLAYING_TAIL_MS = 350;

const PLAY_ICON =
  '<svg class="icon-play" viewBox="0 0 24 24" aria-hidden="true"><path d="M8.5 5.8v12.4a.8.8 0 0 0 1.2.7l9.6-6.2a.8.8 0 0 0 0-1.4L9.7 5.1a.8.8 0 0 0-1.2.7z"/></svg><span class="spinner" aria-hidden="true"></span>';

function readToken(element: Element, name: string, fallback: string) {
  return getComputedStyle(element).getPropertyValue(name).trim() || fallback;
}

export function mountChordLibrary(options: ChordLibraryOptions): ChordLibrary {
  const { root, groups, summary, player, signal } = options;
  const chips = new Map<string, HTMLButtonElement>();
  const flashTimers = new Map<string, ReturnType<typeof setTimeout>>();
  const card = document.createElement('div');
  const play = document.createElement('button');
  const figure = document.createElement('div');
  const notes = document.createElement('p');
  const message = document.createElement('p');
  let activeChip: HTMLButtonElement | null = null;
  let hideTimer: ReturnType<typeof setTimeout> | null = null;

  card.className = 'chord-popup';
  card.id = options.cardId;
  card.hidden = true;
  card.setAttribute('role', 'group');
  play.className = 'chord-popup__play';
  play.type = 'button';
  play.innerHTML = PLAY_ICON;
  figure.className = 'chord-popup__figure';
  notes.className = 'chord-popup__notes';
  message.className = 'chord-popup__message';
  card.append(play, figure, notes, message);
  root.append(card);

  function resolve(chord: string): ChordCard {
    return (
      player.resolveChord(options.getInstrument().id, chord) ?? {
        kind: 'none',
        chord,
        reason: 'no-voicing',
      }
    );
  }

  function describeMissing(popup: Extract<ChordCard, { kind: 'none' }>) {
    const instrument = options.getInstrument().label;

    return popup.reason === 'not-a-chord'
      ? `Open Lyric's chord theory can't read “${popup.chord}” as a chord, so there is nothing to play.`
      : `No playable ${instrument} voicing was found for ${popup.chord}.`;
  }

  // ——— Chords ———

  function renderGroups() {
    groups.replaceChildren(
      ...getOpenLyricChordGroups().map((group) => {
        const section = document.createElement('div');
        const name = document.createElement('h3');
        const list = document.createElement('div');

        section.className = 'chord-group';
        name.className = 'chord-group__name';
        name.textContent = group.name;
        list.className = 'chord-group__chords';
        list.setAttribute('role', 'group');
        list.setAttribute('aria-label', group.name);

        for (const chord of group.chords) {
          const chip = document.createElement('button');

          chip.type = 'button';
          chip.className = 'chord-chip';
          chip.dataset.chord = chord;
          chip.textContent = chord;
          chips.set(chord, chip);
          list.append(chip);
        }

        section.append(name, list);
        return section;
      }),
    );
  }

  function refreshChips() {
    const instrument = options.getInstrument();
    let playable = 0;

    for (const [chord, chip] of chips) {
      const available = getChordCardMidi(resolve(chord)).length > 0;

      playable += Number(available);
      chip.dataset.available = String(available);
      chip.setAttribute(
        'aria-label',
        available
          ? `${chord}, play on ${instrument.label}`
          : `${chord}, nothing to play on ${instrument.label}`,
      );
    }

    summary.textContent = `${playable} of ${chips.size} chords have a voicing on ${instrument.label}.`;
  }

  // ——— The card ———

  function renderCard(chord: string) {
    const popup = resolve(chord);
    const midi = getChordCardMidi(popup);
    const instrument = options.getInstrument();
    const keyText = options.getKey();

    card.dataset.kind = popup.kind;
    card.setAttribute('aria-label', `${chord} on ${instrument.label}`);
    figure.replaceChildren();
    message.textContent = '';

    if (popup.kind === 'diagram') {
      new SVGuitarChord(figure)
        .configure({
          ...popup.chart.settings,
          color: readToken(card, '--diagram-ink', '#1f2328'),
          fingerColor: readToken(card, '--diagram-dot', '#3f4650'),
          fingerStrokeColor: readToken(card, '--diagram-dot', '#3f4650'),
          fingerTextColor: readToken(card, '--diagram-dot-text', '#ffffff'),
          svgTitle: `${instrument.label} diagram for ${chord}`,
        })
        .chord(popup.chart.chord)
        .draw();

      if (popup.voicing.source === 'computed') {
        message.textContent = 'Voicing computed from the chord’s notes.';
      }
    } else {
      const title = document.createElement('p');

      title.className = 'chord-popup__title';
      title.textContent = chord;
      figure.append(title);

      if (popup.kind === 'piano') {
        figure.append(createPianoBoard(chord, popup.piano, keyText));
      } else {
        message.textContent = describeMissing(popup);
      }
    }

    notes.textContent = midi
      .map((note) => getMidiNoteName(note, keyText))
      .join(' ');
    notes.hidden = !midi.length;
    message.hidden = !message.textContent;
    play.disabled = !midi.length;
    play.setAttribute(
      'aria-label',
      midi.length
        ? `Play ${chord} on ${instrument.label}`
        : `Nothing to play for ${chord}`,
    );
    play.title = play.getAttribute('aria-label')!;
    syncPlayButton();
  }

  function syncPlayButton() {
    play.dataset.state = (activeChip && activeChip.dataset.state) || '';
  }

  function placeCard(chip: HTMLElement) {
    const anchor = chip.getBoundingClientRect();
    const { offsetWidth: width, offsetHeight: height } = card;
    let top = anchor.top - height - CARD_GAP_PX;

    if (top < VIEWPORT_MARGIN_PX) {
      top = anchor.bottom + CARD_GAP_PX;
    }

    const left = Math.max(
      VIEWPORT_MARGIN_PX,
      Math.min(
        anchor.left + anchor.width / 2 - width / 2,
        window.innerWidth - width - VIEWPORT_MARGIN_PX,
      ),
    );

    card.style.top = `${Math.round(top)}px`;
    card.style.left = `${Math.round(left)}px`;
  }

  function cancelHide() {
    if (hideTimer != null) {
      clearTimeout(hideTimer);
      hideTimer = null;
    }
  }

  function showCard(chip: HTMLButtonElement) {
    cancelHide();

    if (chip !== activeChip || card.hidden) {
      activeChip?.classList.remove('is-open');
      activeChip?.removeAttribute('aria-describedby');
      activeChip = chip;
      chip.classList.add('is-open');
      chip.setAttribute('aria-describedby', card.id);
      // Shown first: SVGuitar measures its title as it draws, and text in a
      // hidden card measures zero.
      card.hidden = false;
      renderCard(chip.dataset.chord!);
    }

    placeCard(chip);
  }

  function hideCard() {
    cancelHide();
    card.hidden = true;
    activeChip?.classList.remove('is-open');
    activeChip?.removeAttribute('aria-describedby');
    activeChip = null;
  }

  function scheduleHide() {
    cancelHide();
    hideTimer = setTimeout(hideCard, HIDE_DELAY_MS);
  }

  // ——— Playing ———

  function setChipState(chord: string, state: '' | 'loading' | 'playing') {
    const chip = chips.get(chord);

    if (chip) {
      chip.dataset.state = state;
    }

    syncPlayButton();
  }

  function flash(
    chord: string,
    noteCount: number,
    instrument: StrumInstrument,
  ) {
    clearTimeout(flashTimers.get(chord));
    setChipState(chord, 'playing');
    flashTimers.set(
      chord,
      setTimeout(
        () => {
          flashTimers.delete(chord);
          setChipState(chord, '');
        },
        (START_DELAY_SECONDS +
          getChordRollSeconds(getStrumSound(instrument.id), noteCount)) *
          1000 +
          PLAYING_TAIL_MS,
      ),
    );
  }

  async function playChord(chord: string) {
    const midi = getChordCardMidi(resolve(chord));

    if (!midi.length) {
      return;
    }

    const instrument = options.getInstrument();

    setChipState(chord, 'loading');

    try {
      const played = await player.playChord(chord, instrument.id);

      if (played) {
        flash(chord, midi.length, instrument);
      } else {
        setChipState(chord, '');
      }
    } catch (error) {
      setChipState(chord, '');
      options.onError(
        `Could not play ${chord}: ${error instanceof Error ? error.message : String(error)}`,
      );
    }
  }

  // ——— Wiring ———

  function chipFrom(target: EventTarget | null): HTMLButtonElement | null {
    return target instanceof Element
      ? target.closest<HTMLButtonElement>('.chord-chip')
      : null;
  }

  groups.addEventListener('pointerover', (event) => {
    const chip = chipFrom(event.target);

    if (chip) {
      showCard(chip);
    }
  });

  groups.addEventListener('pointerout', (event) => {
    const chip = chipFrom(event.target);
    const next = event.relatedTarget;

    if (
      chip &&
      !(next instanceof Node && (chip.contains(next) || card.contains(next)))
    ) {
      scheduleHide();
    }
  });

  groups.addEventListener('focusin', (event) => {
    const chip = chipFrom(event.target);

    if (chip) {
      showCard(chip);
    }
  });

  groups.addEventListener('focusout', (event) => {
    const next = event.relatedTarget;

    if (!(next instanceof Node && card.contains(next)) && !chipFrom(next)) {
      scheduleHide();
    }
  });

  groups.addEventListener('click', (event) => {
    const chip = chipFrom(event.target);

    if (chip) {
      showCard(chip);
      void playChord(chip.dataset.chord!);
    }
  });

  card.addEventListener('pointerenter', cancelHide);
  card.addEventListener('pointerleave', scheduleHide);
  play.addEventListener('click', () => {
    if (activeChip) {
      void playChord(activeChip.dataset.chord!);
    }
  });

  document.addEventListener(
    'keydown',
    (event) => {
      if (event.key === 'Escape' && !card.hidden) {
        hideCard();
      }
    },
    { signal },
  );

  document.addEventListener(
    'pointerdown',
    (event) => {
      const target = event.target;

      if (
        !card.hidden &&
        !(target instanceof Node && card.contains(target)) &&
        !chipFrom(target)
      ) {
        hideCard();
      }
    },
    { signal },
  );

  const follow = () => {
    if (activeChip && !card.hidden) {
      placeCard(activeChip);
    }
  };

  window.addEventListener('scroll', follow, {
    passive: true,
    capture: true,
    signal,
  });
  window.addEventListener('resize', follow, { signal });
  signal.addEventListener('abort', () => {
    cancelHide();
    flashTimers.forEach((timer) => clearTimeout(timer));
    flashTimers.clear();
  });

  renderGroups();
  refreshChips();

  return {
    refresh() {
      refreshChips();

      if (activeChip && !card.hidden) {
        renderCard(activeChip.dataset.chord!);
        placeCard(activeChip);
      }
    },
  };
}
