import { get as getTonalChord } from '@tonaljs/chord';
import { get as getInterval } from '@tonaljs/interval';
import { chroma as getNoteChroma } from '@tonaljs/note';
import type { Barre, Chord, ChordSettings, Finger } from 'svguitar';

import { CHORD_KEY_GROUPS } from '../../editor/scripts/shared.ts';
import {
  createSvguitarData,
  scorePosition,
  type ChordDatabase,
  type ChordDatabasePosition,
} from '../OpenLyric/domain/chord-voicings.ts';
import type { StrumInstrumentId } from './instruments.ts';

/**
 * A voicing for every chord Open Lyric offers, on each of the strum player's
 * instruments — what a chord card draws and plays, and what a pattern strums
 * for the song key. Five instruments voice chords; the others borrow one's
 * voicings ({@link getVoicingInstrument}).
 *
 * - **Guitar and ukulele:** the easiest of the positions
 *   `@tombatossals/chords-db` (MIT, the database the editor's chord popup
 *   draws from) has for the chord and the one {@link generateFrettedVoicing}
 *   computes — only those that really spell the chord ({@link spellsChord}),
 *   ranked by the popup's `scorePosition`.
 * - **Baritone ukulele:** computed by {@link generateFrettedVoicing} on its
 *   standard tuning.
 * - **Bass:** the chord's bass note low on the neck, with its fifth and
 *   octave above ({@link getBassVoicing}).
 * - **Piano:** the chord's notes stacked in close root position from octave 3,
 *   a slash chord's bass an octave below.
 *
 * The lowest note of a guitar or baritone voicing is always the chord's bass
 * (its root, or a slash chord's bass). A ukulele is re-entrant — its G string
 * is tuned above its C — so it has no bass, and any inversion will do.
 *
 * Chords are read by Tonal, the music theory the editor uses. A name it cannot
 * read (`Cmaj2`, `Am4`, …) has no voicing on any instrument.
 */

/** Open-string MIDI notes, string order (lowest-pitched course first, except
 * the re-entrant ukulele), in standard tuning. */
export const STANDARD_TUNINGS = {
  guitar: [40, 45, 50, 55, 59, 64], // E2 A2 D3 G3 B3 E4
  ukulele: [67, 60, 64, 69], // G4 C4 E4 A4 — re-entrant
  'baritone-ukulele': [50, 55, 59, 64], // D3 G3 B3 E4
  bass: [28, 33, 38, 43], // E1 A1 D2 G2
} as const satisfies Record<string, readonly number[]>;

export type FrettedInstrumentId = keyof typeof STANDARD_TUNINGS;

/** The instruments whose voicings the others borrow. */
export type VoicingInstrumentId = FrettedInstrumentId | 'piano';

/**
 * The instrument whose voicings `instrument` plays: a classical or electric
 * guitar voices a chord as a guitar does, an electric piano or organ as a
 * piano, an upright bass as a bass.
 */
export function getVoicingInstrument(
  instrument: StrumInstrumentId,
): VoicingInstrumentId {
  switch (instrument) {
    case 'classical-guitar':
    case 'electric-guitar':
      return 'guitar';
    case 'electric-piano':
    case 'organ':
      return 'piano';
    case 'upright-bass':
      return 'bass';
    default:
      return instrument;
  }
}

export interface ChordDatabases {
  guitar: ChordDatabase;
  ukulele: ChordDatabase;
}

export interface OpenLyricChordGroup {
  name: string;
  chords: string[];
}

/** What Open Lyric makes of a chord name. */
export interface ChordSpelling {
  name: string;
  rootChroma: number;
  /** The lowest note: a slash chord's bass, else the root. */
  bassChroma: number;
  /** Every pitch class of the chord, bass included. */
  chromas: number[];
  /** Pitch classes a voicing must sound — all but the perfect fifth and inner
   * extensions a player may leave out. */
  requiredChromas: number[];
  /** The chord's intervals above the root, in semitones, low to high. */
  semitones: number[];
}

export interface FrettedVoicing {
  /** One fret per string, string order; `-1` muted, relative to `baseFret`. */
  frets: number[];
  baseFret: number;
  /** MIDI notes in string order, muted strings left out. */
  midi: number[];
  /** Relative frets a finger lays across. */
  barres: number[];
  /** chords-db fingerings, one per string (0 = none); computed voicings have none. */
  fingers?: number[];
  source: 'chords-db' | 'computed';
}

export interface PianoVoicing {
  /** The keys played, low to high. */
  midi: number[];
  /** The first and last key of the board drawn. */
  lowest: number;
  highest: number;
}

export type ChordCard =
  | {
      kind: 'diagram';
      chord: string;
      voicing: FrettedVoicing;
      chart: { chord: Chord; settings: Partial<ChordSettings> };
    }
  | { kind: 'piano'; chord: string; piano: PianoVoicing }
  | {
      kind: 'none';
      chord: string;
      /** `not-a-chord`: Tonal cannot read the name. `no-voicing`: nothing
       * playable was found for this instrument. */
      reason: 'not-a-chord' | 'no-voicing';
    };

const PIANO_ROOT_OCTAVE_MIDI = 48; // C3
const MAX_FRET = 12;
const FRET_SPAN = 3;
const MAX_FINGERS = 4;
const MUTED_STRING_COST = 1.5;
/**
 * How much easier a computed voicing must score to beat a chords-db position,
 * whose shapes are curated and come with fingerings. Half a fret up the neck
 * scores 6.
 */
const DATABASE_PREFERENCE = 6;

/**
 * Open Lyric's chord list (`CHORD_KEY_GROUPS`, the chords its editor
 * suggests), with each `F# / Gb` pair split into its two spellings.
 */
export function getOpenLyricChordGroups(): OpenLyricChordGroup[] {
  const keyGroups: readonly { name: string; keys: readonly string[] }[] =
    CHORD_KEY_GROUPS;

  return keyGroups.map((group) => ({
    name: group.name,
    chords: group.keys.flatMap((key) =>
      key.split('/').map((spelling) => spelling.trim()),
    ),
  }));
}

function mod12(value: number) {
  return ((value % 12) + 12) % 12;
}

/**
 * Whether an interval is one a voicing may drop: the perfect fifth, and any
 * 9th, 11th or 13th below the chord's top extension.
 */
function isOptionalInterval(name: string, isTop: boolean) {
  const interval = getInterval(name);

  if (interval.empty) {
    return false;
  }

  return (
    (interval.simple === 5 && interval.q === 'P') ||
    (!isTop && [9, 11, 13].includes(interval.num))
  );
}

/** `C#m7/G#` → its root, bass and pitch classes, or `null` if unreadable. */
export function spellChord(chord: string): ChordSpelling | null {
  const name = String(chord ?? '').trim();
  const [head, bass] = name.split('/');
  const tonal = getTonalChord(head);
  const rootChroma = getNoteChroma(tonal.tonic ?? '');

  if (tonal.empty || !tonal.tonic || !Number.isFinite(rootChroma)) {
    return null;
  }

  const bassChroma = bass ? getNoteChroma(bass) : rootChroma;

  if (!Number.isFinite(bassChroma)) {
    return null;
  }

  const semitones = tonal.intervals.map(
    (interval) => getInterval(interval).semitones ?? 0,
  );
  const intervalChromas = semitones.map((step) => mod12(rootChroma + step));
  const required = tonal.intervals
    .filter(
      (interval, index) =>
        !isOptionalInterval(interval, index === tonal.intervals.length - 1),
    )
    .map((interval) =>
      mod12(rootChroma + (getInterval(interval).semitones ?? 0)),
    );

  return {
    name,
    rootChroma,
    bassChroma,
    chromas: [...new Set([bassChroma, ...intervalChromas])],
    requiredChromas: [...new Set([bassChroma, ...required])],
    semitones,
  };
}

/**
 * A voicing spells a chord when it sounds nothing outside it, sounds every
 * required note and — unless `requireBass` is off — has the chord's bass as
 * its lowest note.
 */
export function spellsChord(
  midi: readonly number[],
  spelling: ChordSpelling,
  { requireBass = true }: { requireBass?: boolean } = {},
): boolean {
  if (!midi.length) {
    return false;
  }

  const sounding = new Set(midi.map(mod12));

  return (
    [...sounding].every((chroma) => spelling.chromas.includes(chroma)) &&
    spelling.requiredChromas.every((chroma) => sounding.has(chroma)) &&
    (!requireBass || mod12(Math.min(...midi)) === spelling.bassChroma)
  );
}

/**
 * How hard a voicing is to play, lower being easier: the chord popup's
 * `scorePosition`, plus a cost for every muted string — a strummed chord
 * should ring on as many strings as it can.
 */
function scoreVoicing(position: ChordDatabasePosition) {
  const muted = position.frets.filter((fret) => fret < 0).length;

  return scorePosition(position) + muted * MUTED_STRING_COST;
}

/** MIDI notes of a position, string order, muted strings left out. */
export function getPositionMidi(
  tuning: readonly number[],
  frets: readonly number[],
  baseFret: number,
): number[] {
  const offset = Math.max(baseFret, 1) - 1;

  return frets.flatMap((fret, index) =>
    fret < 0 ? [] : [tuning[index] + (fret === 0 ? 0 : fret + offset)],
  );
}

function* combine(
  options: readonly (readonly number[])[],
  index = 0,
  chosen: number[] = [],
): Generator<number[]> {
  if (index === options.length) {
    yield [...chosen];
    return;
  }

  for (const option of options[index]) {
    chosen.push(option);
    yield* combine(options, index + 1, chosen);
    chosen.pop();
  }
}

/**
 * The easiest playable voicing of `spelling` on a fretted instrument, found by
 * trying every fingering in each four-fret window of the neck:
 *
 * - at least `minNotes` strings sound, each a chord note, next to each
 *   other so the chord can be strummed;
 * - the voicing spells the chord ({@link spellsChord}, with `requireBass`);
 * - no more than four fingers, a barre across the lowest fret counting as one.
 *
 * Ranked like chords-db positions ({@link scoreVoicing}); `null` when nothing
 * fits.
 */
export function generateFrettedVoicing(
  tuning: readonly number[],
  spelling: ChordSpelling,
  {
    requireBass = true,
    minNotes = Math.min(3, tuning.length),
  }: { requireBass?: boolean; minNotes?: number } = {},
): FrettedVoicing | null {
  let best: { frets: number[]; score: number } | null = null;

  for (let low = 1; low + FRET_SPAN <= MAX_FRET; low += 1) {
    const window = [
      0,
      ...Array.from({ length: FRET_SPAN + 1 }, (_, offset) => low + offset),
    ];
    const options = tuning.map((open) => [
      -1,
      ...window.filter((fret) => spelling.chromas.includes(mod12(open + fret))),
    ]);

    for (const frets of combine(options)) {
      const first = frets.findIndex((fret) => fret >= 0);
      const last = frets.findLastIndex((fret) => fret >= 0);
      const sounding = last - first + 1;

      if (
        first === -1 ||
        sounding < minNotes ||
        frets.slice(first, last + 1).includes(-1)
      ) {
        continue;
      }

      const fretted = frets.filter((fret) => fret > 0);
      const lowestFret = Math.min(...fretted);
      const fingers =
        fretted.length > MAX_FINGERS
          ? fretted.filter((fret) => fret !== lowestFret).length + 1
          : fretted.length;

      if (
        fingers > MAX_FINGERS ||
        !spellsChord(getPositionMidi(tuning, frets, 1), spelling, {
          requireBass,
        })
      ) {
        continue;
      }

      const score = scoreVoicing(toPosition(frets));

      if (!best || score < best.score) {
        best = { frets, score };
      }
    }
  }

  if (!best) {
    return null;
  }

  const position = toPosition(best.frets);

  return {
    frets: position.frets,
    baseFret: position.baseFret!,
    midi: getPositionMidi(tuning, best.frets, 1),
    barres: position.barres ?? [],
    source: 'computed',
  };
}

/** Absolute frets → a chords-db-style position, relative to its base fret. */
function toPosition(frets: readonly number[]): ChordDatabasePosition {
  const fretted = frets.filter((fret) => fret > 0);
  const highest = fretted.length ? Math.max(...fretted) : 0;
  const lowest = fretted.length ? Math.min(...fretted) : 0;
  const baseFret = highest <= 4 ? 1 : lowest;
  const relative = frets.map((fret) => (fret > 0 ? fret - baseFret + 1 : fret));
  const relativeFretted = relative.filter((fret) => fret > 0);

  return {
    frets: relative,
    baseFret,
    barres:
      relativeFretted.length > MAX_FINGERS
        ? [Math.min(...relativeFretted)]
        : [],
  };
}

/** A voicing's frets counted from the nut. */
function toAbsoluteFrets(voicing: FrettedVoicing): number[] {
  return voicing.frets.map((fret) =>
    fret > 0 ? fret + voicing.baseFret - 1 : fret,
  );
}

/** chords-db names its roots `C`, `Csharp`/`Db`, …; find the one for a chroma. */
function getDatabaseRoot(database: ChordDatabase, chroma: number) {
  return Object.keys(database.chords).find(
    (root) => getNoteChroma(root.replace('sharp', '#')) === chroma,
  );
}

/** The easiest chords-db position that spells the chord, or `null`. */
export function findDatabaseVoicing(
  database: ChordDatabase,
  tuning: readonly number[],
  spelling: ChordSpelling,
  { requireBass = true }: { requireBass?: boolean } = {},
): (FrettedVoicing & { score: number }) | null {
  const root = getDatabaseRoot(database, spelling.rootChroma);
  let best: (FrettedVoicing & { score: number }) | null = null;

  for (const entry of root ? database.chords[root] : []) {
    for (const position of entry.positions) {
      const baseFret = position.baseFret ?? 1;
      const midi = getPositionMidi(tuning, position.frets, baseFret);

      if (!spellsChord(midi, spelling, { requireBass })) {
        continue;
      }

      const score = scoreVoicing(position);

      if (!best || score < best.score) {
        best = {
          frets: position.frets,
          baseFret,
          midi,
          barres: position.barres ?? [],
          fingers: position.fingers,
          source: 'chords-db',
          score,
        };
      }
    }
  }

  return best;
}

/**
 * A bass line for the chord: its bass note on the lowest string that reaches
 * it within the first four frets, then — for a chord with a perfect fifth and
 * no slash bass — the fifth two frets up on the next string, and the octave
 * two frets up on the string after that.
 */
export function getBassVoicing(spelling: ChordSpelling): FrettedVoicing {
  const tuning = STANDARD_TUNINGS.bass;
  const string = tuning.findIndex(
    (open) => mod12(spelling.bassChroma - open) <= 4,
  );
  const fret = mod12(spelling.bassChroma - tuning[string]);
  const withFifth =
    spelling.bassChroma === spelling.rootChroma &&
    spelling.semitones.includes(7);
  const frets = tuning.map((_, index) => {
    if (index === string) {
      return fret;
    }

    if (index === string + 2 || (withFifth && index === string + 1)) {
      return fret + 2;
    }

    return -1;
  });
  const position = toPosition(frets);

  return {
    frets: position.frets,
    baseFret: position.baseFret!,
    midi: getPositionMidi(tuning, frets, 1),
    barres: position.barres ?? [],
    source: 'computed',
  };
}

const voicingCache = new WeakMap<
  ChordDatabases,
  Map<string, FrettedVoicing | null>
>();

/** The voicing a fretted instrument plays for `spelling`, or `null`. */
export function getFrettedVoicing(
  instrument: FrettedInstrumentId,
  spelling: ChordSpelling,
  databases: ChordDatabases,
): FrettedVoicing | null {
  let cache = voicingCache.get(databases);

  if (!cache) {
    cache = new Map();
    voicingCache.set(databases, cache);
  }

  const cacheKey = `${instrument}|${spelling.name}`;

  if (!cache.has(cacheKey)) {
    cache.set(cacheKey, findFrettedVoicing(instrument, spelling, databases));
  }

  return cache.get(cacheKey)!;
}

function findFrettedVoicing(
  instrument: FrettedInstrumentId,
  spelling: ChordSpelling,
  databases: ChordDatabases,
): FrettedVoicing | null {
  if (instrument === 'bass') {
    return getBassVoicing(spelling);
  }

  const tuning = STANDARD_TUNINGS[instrument];
  const requireBass = instrument !== 'ukulele';
  const fromDatabase =
    instrument === 'guitar' || instrument === 'ukulele'
      ? findDatabaseVoicing(databases[instrument], tuning, spelling, {
          requireBass,
        })
      : null;
  // A ukulele strums all four strings and a guitar at least four when a shape
  // allows; otherwise — and on a baritone ukulele, whose open-position shapes
  // often leave the low D out — three will do.
  const computed =
    (instrument === 'baritone-ukulele'
      ? null
      : generateFrettedVoicing(tuning, spelling, {
          requireBass,
          minNotes: 4,
        })) ?? generateFrettedVoicing(tuning, spelling, { requireBass });

  if (
    fromDatabase &&
    (!computed ||
      fromDatabase.score - DATABASE_PREFERENCE <=
        scoreVoicing(toPosition(toAbsoluteFrets(computed))))
  ) {
    const { score: _score, ...voicing } = fromDatabase;

    return voicing;
  }

  return computed;
}

/** The chord in close root position from octave 3, slash bass below. */
export function getPianoVoicing(spelling: ChordSpelling): PianoVoicing {
  const root = PIANO_ROOT_OCTAVE_MIDI + spelling.rootChroma;
  const midi = spelling.semitones.map((step) => root + step);

  if (spelling.bassChroma !== spelling.rootChroma) {
    midi.unshift(PIANO_ROOT_OCTAVE_MIDI - 12 + spelling.bassChroma);
  }

  const sorted = [...new Set(midi)].sort((left, right) => left - right);
  const lowest = sorted[0] - mod12(sorted[0]);
  const top = sorted[sorted.length - 1];

  return {
    midi: sorted,
    lowest,
    highest: top - mod12(top) + 11,
  };
}

/** SVGuitar data and settings for a fretted voicing. */
export function getChordChart(
  instrument: FrettedInstrumentId,
  chord: string,
  voicing: FrettedVoicing,
): { chord: Chord; settings: Partial<ChordSettings> } {
  const data = createSvguitarData(voicing);

  return {
    chord: {
      fingers: data.fingers as Finger[],
      barres: data.barres as Barre[],
    },
    settings: {
      title: chord,
      strings: voicing.frets.length,
      frets: 4,
      position: voicing.baseFret,
      fixedDiagramPosition: true,
      tuning: [],
      strokeWidth: 1.5,
      fingerSize: 0.7,
      fretLabelFontSize: 40,
      titleFontSize: 48,
      sidePadding: instrument === 'guitar' ? 0.2 : 0.3,
    },
  };
}

/** What a chord card shows, and plays, for `chord` on `instrument`. */
export function resolveChordCard(
  instrument: StrumInstrumentId,
  chord: string,
  databases: ChordDatabases,
): ChordCard {
  const name = String(chord ?? '').trim();
  const spelling = spellChord(name);

  if (!spelling) {
    return { kind: 'none', chord: name, reason: 'not-a-chord' };
  }

  const family = getVoicingInstrument(instrument);

  if (family === 'piano') {
    return { kind: 'piano', chord: name, piano: getPianoVoicing(spelling) };
  }

  const voicing = getFrettedVoicing(family, spelling, databases);

  return voicing
    ? {
        kind: 'diagram',
        chord: name,
        voicing,
        chart: getChordChart(family, name, voicing),
      }
    : { kind: 'none', chord: name, reason: 'no-voicing' };
}

/** The notes a card plays, in the order they are struck; empty for none. */
export function getChordCardMidi(card: ChordCard): number[] {
  switch (card.kind) {
    case 'diagram':
      return card.voicing.midi;
    case 'piano':
      return card.piano.midi;
    default:
      return [];
  }
}

let databaseLoad: Promise<ChordDatabases> | null = null;

/** Loads the chords-db guitar and ukulele tables once, on demand. */
export function loadChordDatabases(): Promise<ChordDatabases> {
  databaseLoad ??= Promise.all([
    import('@tombatossals/chords-db/lib/guitar.json'),
    import('@tombatossals/chords-db/lib/ukulele.json'),
  ]).then(([guitar, ukulele]) => ({
    guitar: ((guitar as any).default ?? guitar) as ChordDatabase,
    ukulele: ((ukulele as any).default ?? ukulele) as ChordDatabase,
  }));

  databaseLoad.catch(() => {
    databaseLoad = null;
  });

  return databaseLoad;
}
