import type { PianoVoicing } from './chord-library.ts';
import { getMidiNoteName } from './instruments.ts';

/**
 * The piano figure a chord card draws — shared by the playground's chord card
 * and the chord popup's instrument view (`OpenLyricPluginPlayer`). Styled by
 * the `.piano-board*` classes in each surface's sheet.
 */

const WHITE_KEY_WIDTH = 18;
const WHITE_KEY_HEIGHT = 66;
const BLACK_KEY_WIDTH = 12;
const BLACK_KEY_HEIGHT = 40;
const BLACK_CHROMAS = new Set([1, 3, 6, 8, 10]);
const SVG_NS = 'http://www.w3.org/2000/svg';

function createSvgElement<K extends keyof SVGElementTagNameMap>(
  name: K,
  attributes: Record<string, string | number>,
): SVGElementTagNameMap[K] {
  const element = document.createElementNS(SVG_NS, name);

  for (const [attribute, value] of Object.entries(attributes)) {
    element.setAttribute(attribute, String(value));
  }

  return element;
}

/** A keyboard over the chord's octaves, its keys lit and named. */
export function createPianoBoard(
  chord: string,
  piano: PianoVoicing,
  keyText: string,
) {
  const keys = Array.from(
    { length: piano.highest - piano.lowest + 1 },
    (_, index) => piano.lowest + index,
  );
  const whites = keys.filter((midi) => !BLACK_CHROMAS.has(midi % 12));
  const width = whites.length * WHITE_KEY_WIDTH;
  const svg = createSvgElement('svg', {
    class: 'piano-board',
    viewBox: `0 0 ${width + 1} ${WHITE_KEY_HEIGHT + 1}`,
    role: 'img',
    'aria-label': `Piano keys for ${chord}: ${piano.midi.map((midi) => getMidiNoteName(midi, keyText)).join(' ')}`,
  });
  const drawKey = (midi: number, x: number, black: boolean) => {
    const lit = piano.midi.includes(midi);

    svg.append(
      createSvgElement('rect', {
        class: `piano-board__${black ? 'black' : 'white'}${lit ? ' is-lit' : ''}`,
        x: x + 0.5,
        y: 0.5,
        width: black ? BLACK_KEY_WIDTH : WHITE_KEY_WIDTH,
        height: black ? BLACK_KEY_HEIGHT : WHITE_KEY_HEIGHT,
        rx: 2,
      }),
    );

    if (lit) {
      const label = createSvgElement('text', {
        class: 'piano-board__label',
        x: x + 0.5 + (black ? BLACK_KEY_WIDTH : WHITE_KEY_WIDTH) / 2,
        y: black ? BLACK_KEY_HEIGHT - 6 : WHITE_KEY_HEIGHT - 8,
        'text-anchor': 'middle',
      });

      label.textContent = getMidiNoteName(midi, keyText).replace(/-?\d+$/, '');
      svg.append(label);
    }
  };

  whites.forEach((midi, index) =>
    drawKey(midi, index * WHITE_KEY_WIDTH, false),
  );
  keys
    .filter((midi) => BLACK_CHROMAS.has(midi % 12))
    .forEach((midi) => {
      const whitesBelow = whites.filter((white) => white < midi).length;

      drawKey(midi, whitesBelow * WHITE_KEY_WIDTH - BLACK_KEY_WIDTH / 2, true);
    });

  return svg;
}
