import type { StrumSound } from './instrument-sounds.ts';
import type { WebAudioFontPreset, WebAudioFontZone } from './webaudiofont.ts';

/**
 * The strum player's voice engine: plays soundfont samples the way a real
 * instrument sounds them, on the audio clock. It is this repo's own MIT code;
 * WebAudioFont only loads and decodes the samples (`webaudiofont.ts`).
 *
 * Each note is its sample, pitched from the soundfont zone nearest its key,
 * through a chain of its own:
 *
 * - **Tone** — a low-pass that opens with force and pitch, since a soft stroke
 *   is darker than a hard one and a high string brighter than a low one.
 * - **Envelope** — the sample's own attack and decay. A body's `sustain`
 *   shortens the ring, the sample's loop fades out over `tail` instead of
 *   droning, and no note outlasts `maxRing`. Each zone's level is evened out
 *   against the others, so no string of a chord jumps out, and each sample
 *   starts where it becomes audible — some carry milliseconds of silence
 *   before the pluck, which would make every note late.
 * - **Damper** — a string (`slot`) sounds one note: a new note there lets go
 *   of the old one over `damping`, while the strings it does not touch ring
 *   on. `damp` settles a whole group, as a palm on the strings.
 * - **Pan** — each string or key has its place across the stereo field.
 *
 * The notes of one instrument meet on its bus: the body (a high-pass, a
 * presence peak for a small instrument, and a bass's drive — soft saturation
 * band-limited to the harmonics a small speaker can play, mixed in under the
 * dry sound as an amplifier's would be), then the dry mix and a send into the
 * room — a convolution reverb whose impulse is synthesised here (a warm,
 * 1.3 s room), so no file is loaded for it. A peak limiter keeps loud strums
 * from clipping without flattening them.
 */

export interface StrumNote {
  preset: WebAudioFontPreset;
  sound: StrumSound;
  /** MIDI note. */
  pitch: number;
  /** Audio-clock time it sounds. */
  time: number;
  /** Loudness, 0–1. */
  velocity: number;
  /** Cents off pitch. */
  detune?: number;
  /** −1 (left) to 1 (right). */
  pan?: number;
  /** The string or key it sounds on: a new note there damps this one. */
  slot: string;
  /** The notes `damp` settles together, e.g. a pattern's or a chord card's. */
  group: string;
}

export interface StrumVoice {
  /** Audio-clock time the note sounds. */
  readonly time: number;
  /** Silences the note if it has not sounded yet; a sounding note rings on. */
  cancel(): void;
}

export interface StrumSoundEngine {
  /** Schedules a note; `null` when the soundfont has no sample for it. */
  play(note: StrumNote): StrumVoice | null;
  /**
   * Lets go of every note of `group` from `time`, over `timeConstant`. Notes
   * that would only sound after `time` are cancelled.
   */
  damp(group: string, time: number, timeConstant: number): void;
}

/** How a zone's sample is played: its level correction and where it starts. */
export interface ZoneTrim {
  /** Evens the zone's level out against the preset's other zones. */
  gain: number;
  /** Seconds into the sample it becomes audible. */
  start: number;
}

/** A note's fade-in, over the sample's own attack, so no start clicks. */
const ATTACK_SECONDS = 0.002;
/** The last fade, before a sample without a loop runs out or `maxRing`. */
const END_FADE_SECONDS = 0.08;
/** After this many time constants a damped note is silent (−60 dB). */
const TIME_CONSTANTS_TO_SILENCE = 7;
/** How much a note's gain follows its force: `velocity ** 1.5`. */
const VELOCITY_CURVE = 1.5;
/** A tone filter one octave up the keyboard opens this share of an octave. */
const TONE_KEY_TRACKING = 0.5;
const TONE_MAX_HZ = 18000;
/** Resonance (dB) of a flat, Butterworth-like filter in the Web Audio API. */
const FLAT_Q_DB = -3;
/** How far a zone's level may be evened out, either way. */
const MAX_ZONE_CORRECTION = 2;
/** The stretch of each sample, after its peak, whose level is compared. */
const ZONE_LEVEL_SECONDS = 0.3;
/** Where a sample's peak is looked for: its attack. */
const ZONE_PEAK_SECONDS = 0.5;
/** A sample becomes audible where it first reaches this share of its peak (−40 dB). */
const AUDIBLE_SHARE = 0.01;
/** How much of the silence before that a note keeps, so its onset stays whole. */
const ONSET_MARGIN_SECONDS = 0.0005;
/** WebAudioFont's rate for a zone that names none. */
const DEFAULT_SAMPLE_RATE = 44100;
/** The band a bass's drive adds its harmonics in (Hz). */
const DRIVE_BAND = { low: 120, high: 1600 } as const;
/** How hard the drive saturates. */
const DRIVE_GAIN = 3;
/** Its lean to one side, for the even harmonics an amplifier adds. */
const DRIVE_ASYMMETRY = 0.2;

export const ROOM = {
  /** Seconds the room takes to fall 60 dB. */
  decay: 1.3,
  /** Seconds before the first reflection. */
  preDelay: 0.012,
  /** How much darker the tail grows than the first reflections (0–1). */
  damping: 0.85,
} as const;

const MASTER_GAIN = 0.7;
/**
 * A peak limiter, not a compressor: it touches only the loudest strum attacks
 * (the top 4 dB), so a pick's transient keeps its bite. Its automatic makeup
 * gain lifts the whole mix about 2 dB.
 */
const LIMITER = {
  threshold: -4,
  knee: 3,
  ratio: 12,
  attack: 0.002,
  release: 0.12,
} as const;

/** A zone's key: its root, after the soundfont's tuning (semitones). */
export function getZoneRoot(zone: WebAudioFontZone): number {
  return (
    (zone.originalPitch ?? 6000) / 100 -
    (zone.coarseTune ?? 0) -
    (zone.fineTune ?? 0) / 100
  );
}

/**
 * The zone that sounds `pitch`: of those whose key range holds it, the one
 * whose root is nearest; else the zone whose range is nearest.
 */
export function findZone(
  preset: WebAudioFontPreset,
  pitch: number,
): WebAudioFontZone | null {
  let best: WebAudioFontZone | null = null;
  let bestDistance = Infinity;

  for (const zone of preset.zones) {
    const low = zone.keyRangeLow ?? 0;
    const high = zone.keyRangeHigh ?? 127;
    const outside = pitch < low ? low - pitch : pitch > high ? pitch - high : 0;
    // A zone that holds the pitch always beats one that does not.
    const distance = outside * 1000 + Math.abs(pitch - getZoneRoot(zone));

    if (distance < bestDistance) {
      best = zone;
      bestDistance = distance;
    }
  }

  return best;
}

/** Whether the zone has a sustain loop (WebAudioFont's rule). */
export function hasLoop(zone: WebAudioFontZone): boolean {
  return (
    (zone.loopStart ?? 0) >= 1 && (zone.loopEnd ?? 0) > (zone.loopStart ?? 0)
  );
}

/** Low-pass cutoff (Hz) for a note of `velocity` at `pitch`. */
export function getToneCutoff(
  sound: StrumSound,
  velocity: number,
  pitch: number,
): number {
  const force = Math.min(1, Math.max(0, (velocity - 0.4) / 0.6));
  const cutoff =
    sound.tone.soft *
    (sound.tone.hard / sound.tone.soft) ** force *
    2 ** ((TONE_KEY_TRACKING * (pitch - 60)) / 12);

  return Math.min(TONE_MAX_HZ, Math.max(sound.tone.soft / 2, cutoff));
}

/**
 * The gain a note of `velocity` sounds at, before its zone and instrument:
 * `velocity ** 1.5`, as far as the instrument's `dynamics` lets force count.
 */
export function getVelocityGain(velocity: number, dynamics = 1): number {
  const force = Math.max(0, Math.min(1, velocity)) ** VELOCITY_CURVE;

  return 1 - dynamics + dynamics * force;
}

/**
 * The drive's transfer curve: a soft saturation leaning to one side, so it
 * adds both odd and even harmonics, from −1 to 1 over `size` points.
 */
export function createDriveCurve(size = 1024): Float32Array<ArrayBuffer> {
  const curve = new Float32Array(size);

  for (let i = 0; i < size; i += 1) {
    const x = (i / (size - 1)) * 2 - 1;

    curve[i] = Math.tanh(DRIVE_GAIN * x) + DRIVE_ASYMMETRY * x * x;
  }

  return curve;
}

/**
 * A sample's level — its RMS over {@link ZONE_LEVEL_SECONDS} from its peak —
 * and where it becomes audible, just before it first reaches −40 dB.
 */
function measureSample(buffer: AudioBuffer): { level: number; start: number } {
  const data = buffer.getChannelData(0);
  const rate = buffer.sampleRate;
  const attackEnd = Math.min(data.length, Math.round(ZONE_PEAK_SECONDS * rate));
  let peak = 0;
  let peakIndex = 0;

  for (let i = 0; i < attackEnd; i += 1) {
    const value = Math.abs(data[i]);

    if (value > peak) {
      peak = value;
      peakIndex = i;
    }
  }

  let audible = 0;

  while (
    audible < peakIndex &&
    Math.abs(data[audible]) < peak * AUDIBLE_SHARE
  ) {
    audible += 1;
  }

  const end = Math.min(
    data.length,
    peakIndex + Math.round(ZONE_LEVEL_SECONDS * rate),
  );
  let sum = 0;

  for (let i = peakIndex; i < end; i += 1) {
    sum += data[i] * data[i];
  }

  return {
    level: Math.sqrt(sum / Math.max(1, end - peakIndex)),
    start: Math.max(0, audible / rate - ONSET_MARGIN_SECONDS),
  };
}

const zoneTrims = new WeakMap<
  WebAudioFontPreset,
  Map<WebAudioFontZone, ZoneTrim>
>();

/**
 * How to play a zone's sample, measured once per preset: the gain that evens
 * its level out — the preset's median level over the zone's, within ×½ to
 * ×2 — and the silence to skip before it.
 */
export function getZoneTrim(
  preset: WebAudioFontPreset,
  zone: WebAudioFontZone,
): ZoneTrim {
  let trims = zoneTrims.get(preset);

  if (!trims) {
    const measured = new Map<
      WebAudioFontZone,
      { level: number; start: number }
    >();

    for (const each of preset.zones) {
      if (each.buffer) {
        measured.set(each, measureSample(each.buffer));
      }
    }

    const levels = [...measured.values()]
      .map(({ level }) => level)
      .filter((level) => level > 0)
      .sort((a, b) => a - b);
    const median = levels[Math.floor(levels.length / 2)] ?? 0;

    trims = new Map();

    for (const [each, { level, start }] of measured) {
      trims.set(each, {
        gain:
          level > 0 && median > 0
            ? Math.min(
                MAX_ZONE_CORRECTION,
                Math.max(1 / MAX_ZONE_CORRECTION, median / level),
              )
            : 1,
        start,
      });
    }

    zoneTrims.set(preset, trims);
  }

  return trims.get(zone) ?? { gain: 1, start: 0 };
}

/**
 * A stereo room impulse: noise decaying `decay` seconds to −60 dB after a
 * short pre-delay, darkening as it fades, each channel drawn apart so the room
 * sounds wide.
 */
export function createRoomImpulse(
  sampleRate: number,
  random: () => number = Math.random,
  { decay, preDelay, damping }: typeof ROOM = ROOM,
): [Float32Array, Float32Array] {
  const length = Math.round((preDelay + decay) * sampleRate);
  const delay = Math.round(preDelay * sampleRate);
  const channels: [Float32Array, Float32Array] = [
    new Float32Array(length),
    new Float32Array(length),
  ];

  for (const data of channels) {
    let low = 0;

    for (let i = delay; i < length; i += 1) {
      const t = (i - delay) / sampleRate;
      // −60 dB at `decay`: e^(−6.9·t/decay).
      const level = Math.exp((-6.9 * t) / decay);
      // A one-pole low-pass closing as the tail fades: air and walls take the
      // highs first.
      const smoothing = damping * Math.min(1, t / decay) ** 0.5;

      low = low * smoothing + (random() * 2 - 1) * (1 - smoothing);
      data[i] = low * level;
    }
  }

  return channels;
}

interface Bus {
  input: GainNode;
}

interface Voice extends StrumVoice {
  slot: string;
  group: string;
  /** When the note stops sounding (scheduled). */
  end: number;
  source: AudioBufferSourceNode;
  damper: GainNode;
  /** Settled already: by a damp, a cancel, or its end. */
  done: boolean;
}

export class WebAudioStrumSoundEngine implements StrumSoundEngine {
  #context: BaseAudioContext;
  #master: GainNode;
  #room: AudioNode;
  #buses = new Map<StrumSound, Bus>();
  #slots = new Map<string, Voice>();
  #groups = new Map<string, Set<Voice>>();

  constructor(
    context: BaseAudioContext,
    destination: AudioNode = context.destination,
  ) {
    this.#context = context;

    const limiter = context.createDynamicsCompressor();

    limiter.threshold.value = LIMITER.threshold;
    limiter.knee.value = LIMITER.knee;
    limiter.ratio.value = LIMITER.ratio;
    limiter.attack.value = LIMITER.attack;
    limiter.release.value = LIMITER.release;
    limiter.connect(destination);

    this.#master = context.createGain();
    this.#master.gain.value = MASTER_GAIN;
    this.#master.connect(limiter);

    const convolver = context.createConvolver();
    const impulse = context.createBuffer(
      2,
      Math.round((ROOM.preDelay + ROOM.decay) * context.sampleRate),
      context.sampleRate,
    );

    createRoomImpulse(context.sampleRate).forEach((data, channel) =>
      impulse.getChannelData(channel).set(data),
    );
    convolver.buffer = impulse;
    convolver.connect(this.#master);
    this.#room = convolver;
  }

  play(note: StrumNote): StrumVoice | null {
    const zone = findZone(note.preset, note.pitch);
    const buffer = zone?.buffer;

    if (!zone || !buffer) {
      return null;
    }

    const context = this.#context;
    const { sound } = note;
    const time = Math.max(note.time, context.currentTime);
    const rate =
      2 ** ((note.pitch - getZoneRoot(zone) + (note.detune ?? 0) / 100) / 12);
    const source = context.createBufferSource();
    const loops = hasLoop(zone);
    const delay = zone.delay ?? 0;
    const trim = getZoneTrim(note.preset, zone);
    const offset = delay + trim.start;

    source.buffer = buffer;
    source.playbackRate.value = rate;

    if (loops) {
      const sampleRate = zone.sampleRate ?? DEFAULT_SAMPLE_RATE;

      source.loop = true;
      source.loopStart = zone.loopStart! / sampleRate + delay;
      source.loopEnd = zone.loopEnd! / sampleRate + delay;
    }

    // How long the sample plays, in real time, before its loop or its end.
    const natural =
      Math.max(0, (loops ? source.loopStart : buffer.duration) - offset) / rate;
    const ring = Math.max(
      ATTACK_SECONDS + END_FADE_SECONDS,
      loops ? sound.maxRing : Math.min(sound.maxRing, natural),
    );
    const end = time + ring;

    const tone = context.createBiquadFilter();

    tone.type = 'lowpass';
    tone.frequency.value = getToneCutoff(sound, note.velocity, note.pitch);
    tone.Q.value = FLAT_Q_DB;

    const envelope = context.createGain();
    const gain = envelope.gain;

    gain.setValueAtTime(0, time);
    gain.linearRampToValueAtTime(
      getVelocityGain(note.velocity, sound.dynamics) * trim.gain,
      time + ATTACK_SECONDS,
    );

    if (sound.sustain > 0) {
      gain.setTargetAtTime(0, time + ATTACK_SECONDS, sound.sustain);
    }

    if (loops && natural < ring) {
      gain.setTargetAtTime(
        0,
        time + Math.max(ATTACK_SECONDS, natural),
        sound.tail,
      );
    }

    gain.setTargetAtTime(0, end - END_FADE_SECONDS, END_FADE_SECONDS / 5);

    const damper = context.createGain();
    const panner =
      note.pan && typeof context.createStereoPanner === 'function'
        ? context.createStereoPanner()
        : null;

    source.connect(tone);
    tone.connect(envelope);
    envelope.connect(damper);

    if (panner) {
      panner.pan.value = Math.max(-1, Math.min(1, note.pan!));
      damper.connect(panner);
      panner.connect(this.#getBus(sound).input);
    } else {
      damper.connect(this.#getBus(sound).input);
    }

    const voice: Voice = {
      time,
      end,
      slot: note.slot,
      group: note.group,
      source,
      damper,
      done: false,
      cancel: () => {
        if (!voice.done && voice.time > context.currentTime) {
          this.#stopVoice(voice, context.currentTime);
        }
      },
    };

    source.onended = () => {
      voice.done = true;
      this.#forget(voice);
      source.disconnect();
      damper.disconnect();
      panner?.disconnect();
    };
    source.start(time, offset);
    source.stop(end);

    const previous = this.#slots.get(note.slot);

    if (previous && !previous.done) {
      this.#dampVoice(previous, time, sound.damping);
    }

    this.#slots.set(note.slot, voice);

    let group = this.#groups.get(note.group);

    if (!group) {
      group = new Set();
      this.#groups.set(note.group, group);
    }

    group.add(voice);
    return voice;
  }

  damp(group: string, time: number, timeConstant: number): void {
    for (const voice of this.#groups.get(group) ?? []) {
      this.#dampVoice(voice, time, timeConstant);
    }
  }

  #dampVoice(voice: Voice, time: number, timeConstant: number) {
    if (voice.done) {
      return;
    }

    if (voice.time >= time) {
      this.#stopVoice(voice, this.#context.currentTime);
      return;
    }

    const stop = time + timeConstant * TIME_CONSTANTS_TO_SILENCE;

    voice.done = true;
    voice.damper.gain.setTargetAtTime(0, time, timeConstant);

    if (stop < voice.end) {
      voice.end = stop;
      stopSource(voice.source, stop);
    }
  }

  #stopVoice(voice: Voice, time: number) {
    voice.done = true;
    voice.end = time;
    stopSource(voice.source, time);
    this.#forget(voice);
  }

  #forget(voice: Voice) {
    if (this.#slots.get(voice.slot) === voice) {
      this.#slots.delete(voice.slot);
    }

    this.#groups.get(voice.group)?.delete(voice);
  }

  #getBus(sound: StrumSound): Bus {
    let bus = this.#buses.get(sound);

    if (!bus) {
      const context = this.#context;
      const input = context.createGain();
      const highpass = context.createBiquadFilter();
      const send = context.createGain();
      let output: AudioNode = highpass;

      input.gain.value = sound.level;
      highpass.type = 'highpass';
      highpass.frequency.value = sound.body.highpass;
      highpass.Q.value = FLAT_Q_DB;
      input.connect(highpass);

      if (sound.body.presence) {
        const presence = context.createBiquadFilter();

        presence.type = 'peaking';
        presence.frequency.value = sound.body.presence.frequency;
        presence.gain.value = sound.body.presence.gain;
        presence.Q.value = 1;
        highpass.connect(presence);
        output = presence;
      }

      if (sound.body.drive) {
        output = this.#addDrive(output, sound.body.drive);
      }

      send.gain.value = sound.room;
      output.connect(this.#master);
      output.connect(send);
      send.connect(this.#room);
      bus = { input };
      this.#buses.set(sound, bus);
    }

    return bus;
  }

  /**
   * Mixes a drive into `body`: the dry sound plus `amount` of its soft
   * saturation, kept to {@link DRIVE_BAND}. Returns the node carrying both.
   */
  #addDrive(body: AudioNode, amount: number): AudioNode {
    const context = this.#context;
    const sum = context.createGain();
    const shaper = context.createWaveShaper();
    const low = context.createBiquadFilter();
    const high = context.createBiquadFilter();
    const mix = context.createGain();

    shaper.curve = createDriveCurve();
    shaper.oversample = '2x';
    // The high-pass also takes away the curve's lean, a DC offset.
    low.type = 'highpass';
    low.frequency.value = DRIVE_BAND.low;
    low.Q.value = FLAT_Q_DB;
    high.type = 'lowpass';
    high.frequency.value = DRIVE_BAND.high;
    high.Q.value = FLAT_Q_DB;
    mix.gain.value = amount;
    body.connect(sum);
    body.connect(shaper);
    shaper.connect(low);
    low.connect(high);
    high.connect(mix);
    mix.connect(sum);
    return sum;
  }
}

/** `stop` again, to bring a scheduled end forward; old Safari throws on it. */
function stopSource(source: AudioBufferSourceNode, time: number) {
  try {
    source.stop(time);
  } catch {
    // Already stopped: nothing left to silence.
  }
}
