import { get as getChord, tokenize as tokenizeChord } from '@tonaljs/chord';
import {
  fromSemitones as intervalFromSemitones,
  semitones as intervalSemitones,
} from '@tonaljs/interval';
import { majorKey as getMajorKey, minorKey as getMinorKey } from '@tonaljs/key';
import {
  chroma as getNoteChroma,
  enharmonic as getEnharmonicNote,
  pitchClass as getPitchClass,
  simplify as simplifyNote,
  transpose as transposeNote,
} from '@tonaljs/note';

const CHORD_DATABASE_ROOTS_BY_CHROMA = [
  'C',
  'Csharp',
  'D',
  'Eb',
  'E',
  'F',
  'Fsharp',
  'G',
  'Ab',
  'A',
  'Bb',
  'B',
];

function normalizeMusicTheoryText(value) {
  return String(value ?? '')
    .trim()
    .replace(/♯/g, '#')
    .replace(/♭/g, 'b');
}

function normalizeChordText(value) {
  return normalizeMusicTheoryText(value).replace(/\s+/g, '');
}

function normalizePitchClass(value) {
  return getPitchClass(normalizeMusicTheoryText(value)) || '';
}

function getPitchClassChroma(value) {
  const chroma = getNoteChroma(value);
  return Number.isFinite(chroma) ? chroma : null;
}

function parseMainKey(keyText) {
  const normalizedKeyText = normalizeMusicTheoryText(keyText);

  if (!normalizedKeyText) {
    return null;
  }

  const match = normalizedKeyText.match(/^([A-Ga-g](?:#|b)?)(m)?$/);
  if (!match) {
    return null;
  }

  const tonic = normalizePitchClass(match[1]);
  if (!tonic) {
    return null;
  }

  const isMinor = match[2] === 'm';
  const keyData = isMinor ? getMinorKey(tonic) : getMajorKey(tonic);
  const chroma = getPitchClassChroma(keyData.tonic);

  if (!keyData.tonic || chroma == null) {
    return null;
  }

  return {
    raw: `${keyData.tonic}${isMinor ? 'm' : ''}`,
    tonic: keyData.tonic,
    chroma,
    isMinor,
    alteration: Number.isFinite(keyData.alteration) ? keyData.alteration : 0,
    keySignature: String(keyData.keySignature || ''),
  };
}

function normalizeStructureKeyOption(value) {
  const parsedKey = parseMainKey(value);
  return parsedKey ? parsedKey.raw : normalizeMusicTheoryText(value);
}

function createPitchClassCandidates(chroma) {
  const normalizedChroma = ((Number(chroma) % 12) + 12) % 12;
  const intervalName = intervalFromSemitones(normalizedChroma);
  const flatCandidate = normalizePitchClass(
    simplifyNote(transposeNote('C', intervalName)),
  );
  const sharpCandidate = normalizePitchClass(
    getEnharmonicNote(flatCandidate) || flatCandidate,
  );

  return {
    flatCandidate,
    sharpCandidate: sharpCandidate || flatCandidate,
  };
}

function choosePreferredPitchClass(chroma, targetKey) {
  const { flatCandidate, sharpCandidate } = createPitchClassCandidates(chroma);

  if (!flatCandidate) {
    return '';
  }

  if (!sharpCandidate || sharpCandidate === flatCandidate) {
    return flatCandidate;
  }

  if (!targetKey) {
    return flatCandidate;
  }

  if (targetKey.alteration > 0 || targetKey.raw.includes('#')) {
    return sharpCandidate;
  }

  if (targetKey.alteration < 0 || targetKey.raw.includes('b')) {
    return flatCandidate;
  }

  if (!/[#b]/.test(flatCandidate)) {
    return flatCandidate;
  }

  if (!/[#b]/.test(sharpCandidate)) {
    return sharpCandidate;
  }

  return flatCandidate;
}

function transposePitchClass(noteText, semitoneOffset, targetKeyText) {
  const pitchClass = normalizePitchClass(noteText);
  const pitchClassChroma = getPitchClassChroma(pitchClass);

  if (!pitchClass || pitchClassChroma == null) {
    return normalizeMusicTheoryText(noteText);
  }

  return (
    choosePreferredPitchClass(
      pitchClassChroma + Number(semitoneOffset),
      parseMainKey(targetKeyText),
    ) || pitchClass
  );
}

function transposeChordSymbol(chordText, semitoneOffset, targetKeyText) {
  const normalizedChordText = normalizeChordText(chordText);

  if (!normalizedChordText) {
    return normalizedChordText;
  }

  const [root = '', suffix = '', bassNote = ''] =
    tokenizeChord(normalizedChordText);

  if (!root) {
    return normalizedChordText;
  }

  const nextRoot = transposePitchClass(root, semitoneOffset, targetKeyText);
  const nextBassNote = bassNote
    ? transposePitchClass(bassNote, semitoneOffset, targetKeyText)
    : '';

  return `${nextRoot}${suffix}${nextBassNote ? `/${nextBassNote}` : ''}`;
}

function simplifyChordSymbol(chordText) {
  const normalizedChordText = normalizeChordText(chordText);

  if (!normalizedChordText) {
    return normalizedChordText;
  }

  const [root = '', rawSuffix = ''] = tokenizeChord(normalizedChordText);

  if (!root) {
    return normalizedChordText;
  }

  const normalizedSuffixCandidate = normalizeChordSuffixCandidate(rawSuffix);
  let simplifiedSuffix = rawSuffix;

  if (normalizedSuffixCandidate === 'minor') {
    simplifiedSuffix = 'm';
  } else if (
    /^m(?:6|7|9|11|13)$/.test(normalizedSuffixCandidate) ||
    normalizedSuffixCandidate === 'm7b5' ||
    /^mmaj(?:7|9|11|13|7b5)$/.test(normalizedSuffixCandidate)
  ) {
    simplifiedSuffix = 'm';
  }

  return `${root}${simplifiedSuffix}`;
}

/**
 * The seven diatonic triads of a song key, tonic first — the chords a song in
 * that key most often reaches for (`E` → `E F#m G#m A B C#m D#dim`). Minor
 * keys use the natural minor scale. An unparseable key yields `[]`.
 */
function getKeyDiatonicTriads(keyText) {
  const key = parseMainKey(keyText);

  if (!key) {
    return [];
  }

  const triads = key.isMinor
    ? getMinorKey(key.tonic).natural.triads
    : getMajorKey(key.tonic).triads;

  return Array.from(triads || [], (triad) => String(triad || '')).filter(
    Boolean,
  );
}

function createChordTransposition(sourceKeyText, targetKeyText) {
  const sourceKey = parseMainKey(sourceKeyText);
  const targetKey = parseMainKey(targetKeyText || sourceKeyText);

  if (!sourceKey || !targetKey) {
    return {
      isActive: false,
      semitoneOffset: 0,
      intervalName: intervalFromSemitones(0),
      targetKeyText: normalizeMusicTheoryText(targetKeyText || sourceKeyText),
    };
  }

  const semitoneOffset = (targetKey.chroma - sourceKey.chroma + 12 * 8) % 12;

  return {
    isActive: semitoneOffset !== 0 || sourceKey.raw !== targetKey.raw,
    semitoneOffset,
    intervalName: intervalFromSemitones(semitoneOffset),
    targetKeyText: targetKey.raw,
  };
}

function selectKeyValueForChroma(keyValues, chroma, isMinor) {
  const matchingKeys = (keyValues || [])
    .map((value) => parseMainKey(value))
    .filter((parsedKey) => {
      return (
        parsedKey &&
        parsedKey.isMinor === isMinor &&
        parsedKey.chroma === ((Number(chroma) % 12) + 12) % 12
      );
    })
    .sort((left, right) => {
      const alterationDifference =
        Math.abs(left.alteration) - Math.abs(right.alteration);
      if (alterationDifference) {
        return alterationDifference;
      }

      const preferredAlterationSign = isMinor ? -1 : 1;
      const leftPreferred = left.alteration === preferredAlterationSign;
      const rightPreferred = right.alteration === preferredAlterationSign;
      if (leftPreferred !== rightPreferred) {
        return Number(rightPreferred) - Number(leftPreferred);
      }

      return left.raw.localeCompare(right.raw);
    });

  return matchingKeys[0]?.raw || '';
}

function getAdjacentChromaticKey(keyText, stepOffset, keyValues) {
  const parsedKey = parseMainKey(keyText);

  if (!parsedKey) {
    return normalizeStructureKeyOption(keyText);
  }

  return (
    selectKeyValueForChroma(
      keyValues,
      parsedKey.chroma + Number(stepOffset),
      parsedKey.isMinor,
    ) || parsedKey.raw
  );
}

function normalizeChordSuffixCandidate(value) {
  const normalizedValue = normalizeChordText(value);

  if (!normalizedValue) {
    return 'major';
  }

  if (normalizedValue === '-') {
    return 'minor';
  }

  if (/^(?:M|Maj|maj)$/i.test(normalizedValue)) {
    return 'major';
  }

  if (/^(?:Min|Minor|min|minor)$/i.test(normalizedValue)) {
    return 'minor';
  }

  const leadingMajorMatch = normalizedValue.match(/^M(.+)$/);
  if (leadingMajorMatch) {
    return `maj${leadingMajorMatch[1].toLowerCase()}`;
  }

  const namedMajorMatch = normalizedValue.match(/^Maj(.+)$/i);
  if (namedMajorMatch) {
    return `maj${namedMajorMatch[1].toLowerCase()}`;
  }

  const namedMinorMatch = normalizedValue.match(/^min(?:or)?(.+)$/i);
  if (namedMinorMatch) {
    return `m${namedMinorMatch[1].toLowerCase()}`;
  }

  const mixedMajorMinorMatch = normalizedValue.match(/^m(?:Maj|M)(.+)$/i);
  if (mixedMajorMinorMatch) {
    return `mmaj${mixedMajorMinorMatch[1].toLowerCase()}`;
  }

  if (/^(?:sus|Sus)$/i.test(normalizedValue)) {
    return 'sus4';
  }

  if (/^(?:7sus|7Sus)$/i.test(normalizedValue)) {
    return '7sus4';
  }

  if (/^(?:o|O|°)$/u.test(normalizedValue)) {
    return 'dim';
  }

  if (/^(?:o7|O7|°7)$/u.test(normalizedValue)) {
    return 'dim7';
  }

  if (/^(?:ø|ø7|Ø|Ø7)$/u.test(normalizedValue)) {
    return 'm7b5';
  }

  if (/^\+$/u.test(normalizedValue) || /^augmented$/i.test(normalizedValue)) {
    return 'aug';
  }

  const augmentedMatch = normalizedValue.match(/^\+(.+)$/);
  if (augmentedMatch) {
    return `aug${augmentedMatch[1].toLowerCase()}`;
  }

  if (normalizedValue === '5') {
    return 'major';
  }

  return normalizedValue.toLowerCase();
}

function extractChordDegreeHint(suffixCandidate) {
  const normalizedSuffixCandidate =
    normalizeChordSuffixCandidate(suffixCandidate);

  if (!normalizedSuffixCandidate) {
    return [];
  }

  if (/^(2|4|5|6|7|9|11|13)$/.test(normalizedSuffixCandidate)) {
    return [normalizedSuffixCandidate];
  }

  const qualityDegreeMatch = normalizedSuffixCandidate.match(
    /^(?:maj|m|dim|aug|add|no|omit)(2|4|5|6|7|9|11|13)$/,
  );
  if (qualityDegreeMatch) {
    return [qualityDegreeMatch[1]];
  }

  const suspensionMatch = normalizedSuffixCandidate.match(/^sus(2|4)$/);
  if (suspensionMatch) {
    return [suspensionMatch[1]];
  }

  const dominantSuspensionMatch =
    normalizedSuffixCandidate.match(/^7sus(2|4)$/);
  if (dominantSuspensionMatch) {
    return ['7', dominantSuspensionMatch[1]];
  }

  if (normalizedSuffixCandidate === 'm7b5') {
    return ['7'];
  }

  return [];
}

function createDatabaseSuffixCandidates(rawSuffix, chordInfo) {
  const candidates = [];

  function push(value) {
    const normalizedValue = normalizeChordSuffixCandidate(value);
    if (!normalizedValue || candidates.includes(normalizedValue)) {
      return;
    }

    candidates.push(normalizedValue);
  }

  push(rawSuffix);

  if (!normalizeChordText(rawSuffix)) {
    push('major');
  }

  if (chordInfo && !chordInfo.empty) {
    const [, symbolSuffix = ''] = tokenizeChord(chordInfo.symbol || '');
    push(symbolSuffix);
    chordInfo.aliases.forEach(push);

    if (chordInfo.quality === 'Major' && chordInfo.intervals.length === 3) {
      push('major');
    }

    if (chordInfo.quality === 'Minor' && chordInfo.intervals.length === 3) {
      push('minor');
      push('m');
    }

    if (chordInfo.quality === 'Augmented') {
      push('aug');
    }

    if (chordInfo.quality === 'Diminished') {
      push('dim');
    }
  }

  push('major');

  return candidates;
}

function createChordDegreeHints(chordKey) {
  const normalizedChordKey = normalizeChordText(chordKey);
  const [root = '', rawSuffix = ''] = tokenizeChord(normalizedChordKey);

  if (!root) {
    return [];
  }

  const chordInfo = getChord(normalizedChordKey);
  const hints = [];

  function pushHint(value) {
    if (!value || hints.includes(value)) {
      return;
    }

    hints.push(value);
  }

  createDatabaseSuffixCandidates(rawSuffix, chordInfo).forEach((candidate) => {
    extractChordDegreeHint(candidate).forEach(pushHint);
  });

  if (hints.length || !chordInfo || chordInfo.empty) {
    return hints;
  }

  chordInfo.intervals.forEach((intervalName) => {
    const degreeMatch = String(intervalName).match(/^(2|4|6|7|9|11|13)/);
    if (degreeMatch) {
      pushHint(degreeMatch[1]);
    }
  });

  return hints;
}

function createChordDatabaseSearchData(chordKey) {
  const normalizedChordKey = normalizeChordText(chordKey);
  const [root = '', rawSuffix = '', bassRoot = ''] =
    tokenizeChord(normalizedChordKey);

  if (!root) {
    return null;
  }

  const normalizedRoot = normalizePitchClass(root);
  const rootChroma = getPitchClassChroma(normalizedRoot);

  if (!normalizedRoot || rootChroma == null) {
    return null;
  }

  const normalizedBassRoot = normalizePitchClass(bassRoot);
  const bassPitchClass = normalizedBassRoot
    ? getPitchClassChroma(normalizedBassRoot)
    : null;
  const chordInfo = getChord(normalizedChordKey);

  return {
    bassPitchClass,
    bassRoot: normalizedBassRoot,
    chordInfo,
    datasetRoot: CHORD_DATABASE_ROOTS_BY_CHROMA[rootChroma] || '',
    normalizedChordKey,
    rawSuffix,
    root: normalizedRoot,
    suffixCandidates: createDatabaseSuffixCandidates(rawSuffix, chordInfo),
  };
}

function describeChordKey(chordKey) {
  const normalizedChordKey = normalizeChordText(chordKey);

  if (!normalizedChordKey) {
    return 'Chord';
  }

  const chordInfo = getChord(normalizedChordKey);
  if (!chordInfo.empty && chordInfo.name) {
    return `Chord ${chordInfo.name}`;
  }

  return `Chord ${normalizedChordKey}`;
}

export {
  createChordDatabaseSearchData,
  createChordDegreeHints,
  createChordTransposition,
  describeChordKey,
  getAdjacentChromaticKey,
  getKeyDiatonicTriads,
  normalizeChordText,
  normalizeStructureKeyOption,
  parseMainKey,
  simplifyChordSymbol,
  transposeChordSymbol,
  transposePitchClass,
  intervalSemitones,
};
